import React from 'react';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@ohif/ui-next';

const classNameSelectTrigger =
  'border-default text-default bg-background hover:bg-secondary h-auto min-w-0 rounded border p-1 [&>span]:!block [&>span]:min-w-0 [&>span]:truncate';
const classNameSelectItem = 'text-default focus:bg-secondary focus:text-default';

const WediagSelect = ({
  label,
  value,
  options,
  onChange,
}: {
  label: string;
  value: string;
  options: [string, string][];
  onChange: (value: string) => void;
}) => (
  <div className="flex min-w-0 flex-1 flex-col">
    <span className="text-default text-xs opacity-70">{label}</span>
    <Select
      value={value}
      onValueChange={onChange}
    >
      <SelectTrigger className={classNameSelectTrigger}>
        <SelectValue />
      </SelectTrigger>
      <SelectContent>
        {options.map(([optionValue, optionLabel]) => (
          <SelectItem
            key={optionValue}
            value={optionValue}
            className={classNameSelectItem}
          >
            {optionLabel}
          </SelectItem>
        ))}
      </SelectContent>
    </Select>
  </div>
);

export default WediagSelect;
