import React, { useEffect, useState } from 'react';
import { useTranslation } from 'react-i18next';

import DentalChart, { colors } from '../../../../../extensions/default/src/Panels/DentalChart';
import WediagButton from '../WediagButton';
import PropTypes from 'prop-types';
import { Icons } from '@ohif/ui-next';

const LEGEND = [
  { label: 'Implant placed', color: colors.implantTooth },
  { label: 'Missing tooth', color: colors.missingTooth },
];

interface ViewportImplantFormProps {
  onClose: () => void;
  addImplant: (toothNumber: number) => Promise<boolean>;
  implantTeeth: number[];
  missingTeeth: number[];
  compact: boolean;
  onExpand: () => void;
  defaultToothNumber: number;
  onToothChange: (toothNumber: number) => void;
}

const ViewportImplantForm = ({
  onClose,
  addImplant,
  implantTeeth,
  missingTeeth,
  compact,
  onExpand,
  defaultToothNumber,
  onToothChange,
}: ViewportImplantFormProps) => {
  const { t } = useTranslation('Modals');

  const [toothNumber, setToothNumberState] = useState(defaultToothNumber);

  // Follows the tooth chosen in the other version of the form (compact <-> large)
  useEffect(() => setToothNumberState(defaultToothNumber), [defaultToothNumber]);
  const setToothNumber = (value: number) => {
    setToothNumberState(value);
    onToothChange(value);
  };

  const legend = LEGEND.map(({ label, color }) => (
    <div
      key={label}
      className="text-default flex items-center space-x-2"
    >
      <span
        className="inline-block h-3 w-3 rounded-sm"
        style={{ backgroundColor: color }}
      />
      <span>{label}</span>
    </div>
  ));

  const buttons = (
    <>
      <WediagButton
        buttonCategory="sm"
        variant="bordered"
        onPress={onClose}
        className={compact ? 'flex-1' : ''}
      >
        {t('Cancel')}
      </WediagButton>

      <WediagButton
        buttonCategory="sm"
        variant="bordered"
        onPress={() => addImplant(toothNumber)}
        isDisabled={toothNumber === -1}
        className={compact ? 'flex-1' : ''}
      >
        Confirm
      </WediagButton>
    </>
  );

  if (compact) {
    return (
      <div className="flex w-full flex-col space-y-2">
        <div className="flex items-center justify-between">
          <p className="text-default text-sm">Select tooth for implant</p>
          <button
            type="button"
            title="Enlarge"
            className="text-default grid h-6 w-6 place-items-center rounded hover:opacity-70"
            onClick={onExpand}
          >
            <Icons.ToolExpand />
          </button>
        </div>

        <div className="h-28 w-full">
          <DentalChart
            selectedTooth={toothNumber}
            setSelectedTooth={setToothNumber}
            implantTeeth={implantTeeth}
            missingTeeth={missingTeeth}
          />
        </div>

        <div className="flex flex-wrap gap-x-4 text-xs">{legend}</div>

        <div className="flex w-full space-x-2">{buttons}</div>
      </div>
    );
  }

  return (
    <div className="flex h-full w-full flex-col items-center justify-between">
      <div className="flex h-[70%] w-[70%] items-center justify-center">
        <DentalChart
          selectedTooth={toothNumber}
          setSelectedTooth={setToothNumber}
          implantTeeth={implantTeeth}
          missingTeeth={missingTeeth}
        />
      </div>

      <div className="flex space-x-6">{legend}</div>

      <div className="mb-4 mr-6 flex w-full justify-end space-x-4">{buttons}</div>
    </div>
  );
};

ViewportImplantForm.propTypes = {
  onClose: PropTypes.func.isRequired,
  addImplant: PropTypes.func.isRequired,
  implantTeeth: PropTypes.arrayOf(PropTypes.number).isRequired,
  missingTeeth: PropTypes.arrayOf(PropTypes.number).isRequired,
  compact: PropTypes.bool.isRequired,
  onExpand: PropTypes.func.isRequired,
  defaultToothNumber: PropTypes.number.isRequired,
  onToothChange: PropTypes.func.isRequired,
};

export default ViewportImplantForm;
