import React, { ReactElement, useEffect, useState, RefObject, useCallback, useRef } from 'react';
import TeethManager from '../../assets/teeth/TeethManager';

/* width: width of the 16 teeth of a jaw
height: heigth of the highest tooth of each jaw
spaceJaw: space between jaws
spaceTeeth: space between teeth
totalSpaceTeeth : total space between the teeth */
const DENTAL_CHART: {
  width: number;
  height: number;
  spaceJaw: number;
  spaceTeeth: number;
  totalSpaceTeeth: number;
} = {
  width: 663,
  height: 158 * 2,
  spaceJaw: 30,
  spaceTeeth: 4,
  totalSpaceTeeth: 4 * 16,
};

const UPPER_JAW_TEETH: number[] = [18, 17, 16, 15, 14, 13, 12, 11, 21, 22, 23, 24, 25, 26, 27, 28];
const LOWER_JAW_TEETH: number[] = [48, 47, 46, 45, 44, 43, 42, 41, 31, 32, 33, 34, 35, 36, 37, 38];

interface DentalChartToothStatus {
  num: number;
  hovered: boolean;
}

const colors = {
  implantTooth: '#FFFF74', // DentalChartTooth
  missingTooth: '#808080', // DentalChartTooth
  selected: '#407FA0', // TeethShape
  red: '#FF0000', // TeethShape
  default: '#DCDCDC', // DentalChartTooth
  secondary: '#1F1F1F', // TeethShape
  teeth: '#00D2FF', // TeethShape
  gray: '#808080', // DentalChartTooth
  hoveredTooth: '#B3B3B3', // DentalChartTooth
  selectedTooth: '#4CAF50', // DentalChartTooth
  selectedHoveredTooth: '#388E3C', // DentalChartTooth
  disabledTooth: '#666666', // DentalChartTooth et RenderJawPerio
  selectedHoveredPillarTooth: '#EBD727', // DentalChartTooth
  originTooth: '#F2E55C', // DentalChartTooth
  hover: '#20a5d6', // UserSettings
  yellow: '#FFFF00', // renderJawPerio
};

const DentalChartTooth = ({
  tooth,
  onClick,
  setIsHovered,
  scale,
  selectedTooth,
  hasImplant,
  isMissing,
}: {
  tooth: DentalChartToothStatus;
  onClick: () => void;
  setIsHovered: (valueHover: boolean) => void;
  scale: number;
  selectedTooth: number;
  hasImplant: boolean;
  isMissing: boolean;
}) => {
  const [dynamicComponent, setDynamicComponent] = useState<ReactElement | null>(null);

  // Load the correct tooth, apply the scale to it and set the correct color depending of the status
  useEffect(() => {
    const loadDynamicComponent = async (): Promise<void> => {
      try {
        const fill: string = (() => {
          if (tooth.num === selectedTooth && tooth.hovered) {
            return colors.selectedHoveredTooth;
          } else if (tooth.num === selectedTooth) {
            return colors.selectedTooth;
          } else if (tooth.hovered) {
            return colors.hoveredTooth;
          } else if (tooth.num % 10 === 8) {
            return colors.disabledTooth;
          } else if (hasImplant) {
            return colors.implantTooth;
          } else if (isMissing) {
            return colors.missingTooth;
          } else {
            return colors.default;
          }
        })();

        const instanceComponent = (
          <TeethManager
            toothNumber={tooth.num}
            scale={scale}
            fill={fill}
          />
        );

        setDynamicComponent(instanceComponent);
      } catch (error) {
        console.error('Error while loading dynamic component:', error);
      }
    };

    loadDynamicComponent();
  }, [tooth, scale, selectedTooth, hasImplant, isMissing]);

  return (
    <div
      onClick={onClick}
      onMouseEnter={() => setIsHovered(true)}
      onMouseLeave={() => setIsHovered(false)}
      className="cursor-pointer"
      style={{ marginLeft: DENTAL_CHART.spaceTeeth + 'px' }}
    >
      {dynamicComponent}
    </div>
  );
};

const RenderJaw = ({
  jaw,
  teeth,
  updateTooth,
  scale,
  placeEnd,
  selectedTooth,
  implantTeeth,
  missingTeeth,
}: {
  jaw: number[];
  teeth: DentalChartToothStatus[];
  updateTooth: (num: number, isHover: boolean, valueHover: boolean) => void;
  scale: number;
  placeEnd: boolean;
  selectedTooth: number;
  implantTeeth: number[];
  missingTeeth: number[];
}) => {
  return (
    <div className={`flex justify-center ${placeEnd ? 'place-items-end' : ''}`}>
      {jaw.map((num: number, index: number) => {
        const tooth: DentalChartToothStatus | undefined = teeth.find(
          (element: DentalChartToothStatus) => element.num === num
        );
        return tooth ? (
          <DentalChartTooth
            key={index}
            tooth={tooth}
            onClick={() => updateTooth(num, false, false)}
            setIsHovered={(valueHover: boolean) => updateTooth(num, true, valueHover)}
            scale={scale}
            selectedTooth={selectedTooth}
            hasImplant={implantTeeth.includes(num)}
            isMissing={missingTeeth.includes(num)}
          />
        ) : null;
      })}
    </div>
  );
};

const useDentalChartScale = (): [number, RefObject<HTMLDivElement | null>] => {
  const containerRef: RefObject<HTMLDivElement | null> = useRef<HTMLDivElement | null>(null);
  const [scale, setScale] = useState<number>(0);

  // Calculate the scale so that the dental chart doesn't overflow
  const calculateScale = useCallback((): number => {
    if (containerRef.current) {
      const scaleWidth: number =
        (containerRef.current.offsetWidth - DENTAL_CHART.totalSpaceTeeth) / DENTAL_CHART.width;
      const scaleHeight: number =
        (containerRef.current.offsetHeight - DENTAL_CHART.spaceJaw) / DENTAL_CHART.height;
      const res = Math.min(scaleWidth, scaleHeight);
      if (res < 0) {
        return 1;
      }
      return Math.min(scaleWidth, scaleHeight);
    }
    return 1;
  }, [containerRef]);

  // Update the scale when the window is resized
  useEffect(() => {
    const handleResize = (): void => setScale(calculateScale());

    window.addEventListener('resize', handleResize);
    handleResize();

    return () => window.removeEventListener('resize', handleResize);
  }, [calculateScale]);

  return [scale, containerRef];
};

const DentalChart = ({
  selectedTooth,
  setSelectedTooth,
  implantTeeth = [],
  missingTeeth = [],
}: {
  selectedTooth: number;
  setSelectedTooth: (value: number) => void;
  implantTeeth?: number[];
  missingTeeth?: number[];
}) => {
  const [scale, containerRef] = useDentalChartScale();

  const [teeth, setTeeth] = useState<DentalChartToothStatus[]>(
    [...UPPER_JAW_TEETH, ...LOWER_JAW_TEETH].map((num: number) => ({ num: num, hovered: false }))
  );

  // Update hovered or selected field of the tooth num
  const updateTooth = (num: number, isHover: boolean, valueHover: boolean): void => {
    const currentTooth: DentalChartToothStatus | undefined = teeth.find(
      (element: DentalChartToothStatus) => element.num === num
    );

    if (!currentTooth) {
      return;
    }
    if (!isHover) {
      setSelectedTooth(num);
    } else {
      setTeeth((prevTeeth: DentalChartToothStatus[]) =>
        prevTeeth.map((tooth: DentalChartToothStatus) => {
          if (tooth.num === num) {
            return { ...tooth, hovered: valueHover };
          }
          return tooth;
        })
      );
    }
  };

  return (
    <>
      {/* DENTAL_CHART.spaceJaw = 30 */}
      <div
        ref={containerRef}
        className={`flex h-full w-full flex-col justify-evenly space-y-[30px]`}
      >
        {scale > 0 && (
          <>
            <RenderJaw
              jaw={UPPER_JAW_TEETH}
              teeth={teeth}
              updateTooth={updateTooth}
              scale={scale}
              placeEnd={true}
              selectedTooth={selectedTooth}
              implantTeeth={implantTeeth}
              missingTeeth={missingTeeth}
            />
            <RenderJaw
              jaw={LOWER_JAW_TEETH}
              teeth={teeth}
              updateTooth={updateTooth}
              scale={scale}
              placeEnd={false}
              selectedTooth={selectedTooth}
              implantTeeth={implantTeeth}
              missingTeeth={missingTeeth}
            />
          </>
        )}
      </div>
    </>
  );
};

export default DentalChart;
export { colors };
