import { ChunkEnvelope } from './database';

interface ChunkBuffer {
  total: number;
  parts: Array<string | undefined>;
  lastUpdateMs: number;
}

export interface ReassembleResult {
  completePayload: string | null;
  error?: string;
}

export class ChunkReassembler {
  private buffers = new Map<string, ChunkBuffer>();

  constructor(private readonly timeoutMs: number) {}

  static isChunkEnvelope(payload: unknown): payload is ChunkEnvelope {
    if (!payload || typeof payload !== 'object') {
      return false;
    }
    const candidate = payload as Partial<ChunkEnvelope>;
    return (
      candidate.__wdxChunk === true &&
      typeof candidate.chunkId === 'string' &&
      typeof candidate.seq === 'number' &&
      typeof candidate.total === 'number' &&
      typeof candidate.data === 'string'
    );
  }

  addChunk(envelope: ChunkEnvelope, scope = 'default'): ReassembleResult {
    this.pruneExpired();
    const key = this.buildKey(scope, envelope.chunkId);
    const now = Date.now();

    if (!Number.isInteger(envelope.total) || envelope.total <= 0) {
      return { completePayload: null, error: 'Invalid total chunk count' };
    }
    if (!Number.isInteger(envelope.seq) || envelope.seq < 0 || envelope.seq >= envelope.total) {
      return { completePayload: null, error: 'Invalid chunk sequence' };
    }

    const existing = this.buffers.get(key);
    if (existing && existing.total !== envelope.total) {
      this.buffers.delete(key);
      return { completePayload: null, error: 'Chunk total mismatch' };
    }

    const buffer = existing ?? {
      total: envelope.total,
      parts: new Array<string | undefined>(envelope.total),
      lastUpdateMs: now,
    };
    buffer.parts[envelope.seq] = envelope.data;
    buffer.lastUpdateMs = now;
    this.buffers.set(key, buffer);

    for (const part of buffer.parts) {
      if (typeof part !== 'string') {
        return { completePayload: null };
      }
    }

    this.buffers.delete(key);
    return { completePayload: buffer.parts.join('') };
  }

  clearScope(scope: string): void {
    const prefix = `${scope}::`;
    for (const key of this.buffers.keys()) {
      if (key.startsWith(prefix)) {
        this.buffers.delete(key);
      }
    }
  }

  clearAll(): void {
    this.buffers.clear();
  }

  private buildKey(scope: string, chunkId: string): string {
    return `${scope}::${chunkId}`;
  }

  private pruneExpired(): void {
    const now = Date.now();
    for (const [key, value] of this.buffers.entries()) {
      if (now - value.lastUpdateMs > this.timeoutMs) {
        this.buffers.delete(key);
      }
    }
  }
}
