const pixelDataToPngBuffer = (
  pixelData: Float32Array,
  bitsStored: number,
  windowCenter?: number,
  windowWidth?: number
) => {
  // pngBuf has 4 channels (RGBA)
  const pngBuf = new Uint8ClampedArray(pixelData.length * 4);

  if (windowCenter !== undefined && windowWidth !== undefined) {
    // Use windowing
    const windowBase: number = windowCenter - 0.5;
    const windowRange: number = windowWidth - 1;
    for (let i = 0; i < pixelData.length; i++) {
      const scaledVal: number = ((pixelData[i] - windowBase) / windowRange + 0.5) * 255;
      const idx = i * 4;
      pngBuf[idx] = scaledVal;
      pngBuf[idx + 1] = scaledVal;
      pngBuf[idx + 2] = scaledVal;
      pngBuf[idx + 3] = 255;
    }
  } else {
    const maxVal: number = (1 << bitsStored) - 1;
    const scaleFactor: number = 255 / maxVal;
    for (let i = 0; i < pixelData.length; i++) {
      const scaledVal: number = pixelData[i] * scaleFactor;
      const idx = i * 4;
      pngBuf[idx] = scaledVal;
      pngBuf[idx + 1] = scaledVal;
      pngBuf[idx + 2] = scaledVal;
      pngBuf[idx + 3] = 255;
    }
  }

  return pngBuf;
};

const pngBufferToCanvas = async (
  pngBuf: Uint8ClampedArray<ArrayBuffer>,
  width: number,
  height: number,
  invertRows: boolean = false
) => {
  const imgData = new ImageData(pngBuf, width, height);
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;

  const canvasContext = canvas.getContext('2d');
  if (invertRows) {
    canvasContext.scale(1, -1);
    const bitmap = await createImageBitmap(imgData);
    canvasContext.drawImage(bitmap, 0, -height);
  } else {
    canvasContext.putImageData(imgData, 0, 0);
  }

  return canvas;
};

export { pixelDataToPngBuffer, pngBufferToCanvas };
