import FileLoader from './fileLoader';
import dicomImageLoader from '@cornerstonejs/dicom-image-loader';
import loadPNGImage from './loadPNGImage';

const ImageFileLoader = new (class extends FileLoader {
  fileType = 'image/png';
  loadFile(file, imageId) {
    return dicomImageLoader.wadouri.loadFileRequest(imageId);
  }

  async getDataset(image, imageId, options = {}) {
    const imageObject = await loadPNGImage(imageId).promise;
    const dataset = {
      Rows: imageObject.height,
      Columns: imageObject.width,
      SOPClassUID: '1.2.840.10008.5.1.4.1.1.7',
      Modality: 'OT',
      PixelRepresentation: 0,
      PixelData: new Array(imageObject.getPixelData().buffer),
      PixelSpacing: options?.PixelSpacing ?? [0.4, 0.4],
      SliceThickness: options?.SliceThickness ?? 0.4,
      InstanceNumber: options?.InstanceNumber ?? 1,
      ImageOrientationPatient: [1, 0, 0, 0, 1, 0],
      ImagePositionPatient: options?.ImagePositionPatient ?? [0, 0, 0],
      BitsAllocated: 8,
      BitsStored: 8,
      HighBit: 7,
      imageId,
      SamplesPerPixel: 1,
      PhotometricInterpretation: 'MONOCHROME2',
      SeriesInstanceUID: options?.SeriesInstanceUID ?? Math.random().toString(36).substring(2, 10),
      SOPInstanceUID: options?.SOPInstanceUID ?? Math.random().toString(36).substring(2, 10),
      StudyInstanceUID: options?.StudyInstanceUID ?? Math.random().toString(36).substring(2, 10),
      FrameOfReferenceUID:
        options?.FrameOfReferenceUID ?? Math.random().toString(36).substring(2, 10),
      _meta: {
        TransferSyntaxUID: {
          Value: new Array('1.2.840.10008.1.2.1'),
        },
      },
    };

    return dataset;
  }
})();

export default ImageFileLoader;
