const addControlPointAnnotations = (
  viewport: VolumeViewport,
  imageData: vtkImageData,
  points: Points,
  middleLayer: number,
  { servicesManager }: { servicesManager: AppTypes.ServicesManager }
) => {
  const { toolGroupService } = servicesManager.services;

  // Draw these control points in front on Viewport so that user can move them
  // Get LineSegment instance in order to create new interpolated annotation
  const annotationUIDs: string[] = [];
  const toolGroup = toolGroupService.getToolGroupForViewport(viewport.id) as cstTypes.IToolGroup;
  const lineSegmentInstance = toolGroup.getToolInstance('LineSegment');

  const addAnnotation = (pointsSet: NumberPair[], mode: string, visibility: boolean) => {
    const pointsInWorld = pointsSet.map(cp => imageData.indexToWorld([cp[0], cp[1], middleLayer]));
    // TODO replace with custom annotation
    const pointAnnotation: cstTypes.ToolSpecificAnnotationTypes.ArrowAnnotation =
      lineSegmentInstance.addNewAnnotationWithMode(
        viewport.element,
        pointsInWorld,
        mode,
        'rgb(0, 255, 0)',
        visibility
      );
    annotationUIDs.push(pointAnnotation.annotationUID);
  };

  const { controlPoints, curvePoints, outerPoints, innerPoints } = points;
  addAnnotation(controlPoints, 'movable', false);
  for (const pointsSet of [curvePoints, outerPoints, innerPoints]) {
    addAnnotation(pointsSet, 'points', false);
  }

  return annotationUIDs;
};

const deleteControlPoints = (
  viewport: VolumeViewport,
  annotationUIDs: string[],
  servicesManager: AppTypes.ServicesManager
) => {
  const { measurementService, toolGroupService } = servicesManager.services;

  const toolGroup = toolGroupService.getToolGroupForViewport(viewport.id) as cstTypes.IToolGroup;
  const lineSegmentInstance = toolGroup.getToolInstance('LineSegment');
  for (const annotationUID of annotationUIDs) {
    lineSegmentInstance.removeLineSegmentAnnotation(annotationUID);
    measurementService.remove(annotationUID);
  }
};

const generateAnnotations = (
  panoramicState: PanoramicState,
  imageData: vtkImageData,
  points: Points,
  [minLayer, maxLayer]: NumberPair,
  servicesManager: AppTypes.ServicesManager
) => {
  const { cornerstoneViewportService } = servicesManager.services;

  const viewport = cornerstoneViewportService.getCornerstoneViewport('axial') as VolumeViewport;
  if (panoramicState?.annotationUIDs?.length) {
    // Delete former annotations
    deleteControlPoints(viewport, panoramicState.annotationUIDs, servicesManager);
  }
  const middleLayer = Math.ceil((minLayer + maxLayer) / 2) - 1;
  const annotationUIDs = addControlPointAnnotations(viewport, imageData, points, middleLayer, {
    servicesManager,
  });

  return annotationUIDs;
};

const deletePanoramic = (servicesManager: AppTypes.ServicesManager) => {
  const { segmentationService, displaySetService } = servicesManager.services;

  const dentascanSegmentations = segmentationService.getDentascanSegmentations();
  if (dentascanSegmentations?.length) {
    // Delete former dentascan segmentations
    for (const segmentation of dentascanSegmentations) {
      segmentationService.remove(segmentation.segmentationId);
    }
  }

  const activeDisplaySets = displaySetService.getActiveDisplaySets();
  const panoramicDisplaySet = activeDisplaySets.find(displaySet =>
    displaySet.SeriesInstanceUID.includes('panoramic')
  );
  if (panoramicDisplaySet) {
    displaySetService.deleteDisplaySet(panoramicDisplaySet.displaySetInstanceUID);
  }
  const dentascanDisplaySet = activeDisplaySets.find(displaySet =>
    displaySet.SeriesInstanceUID.includes('dentascan')
  );
  if (dentascanDisplaySet) {
    displaySetService.deleteDisplaySet(dentascanDisplaySet.displaySetInstanceUID);
  }
};

const createDataset = (
  canvas: HTMLCanvasElement,
  datasetOptions: {
    SOPInstanceUID?: string;
    InstanceNumber?: number;
    ImagePositionPatient?: number[];
    PixelSpacing?: NumberPair;
    SliceThickness?: number;
    SeriesInstanceUID: string;
    StudyInstanceUID: string;
    FrameOfReferenceUID?: string;
  }
) => {
  return new Promise((resolve, reject) => {
    canvas.toBlob(async blob => {
      const fileLoaderService = new FileLoaderService(blob);
      const imageId = fileLoaderService.addFile(blob);
      const image = await fileLoaderService.loadFile(blob, imageId);
      const dataset = await fileLoaderService.getDataset(image, imageId, datasetOptions);
      metadataProvider.addImageIdToUIDs(imageId, {
        StudyInstanceUID: dataset.StudyInstanceUID,
        SeriesInstanceUID: dataset.SeriesInstanceUID,
        SOPInstanceUID: dataset.SOPInstanceUID,
        frameIndex: dataset.NumberOfFrames > 1 ? dataset.InstanceNumber : 1,
      });
      resolve(dataset);
    });
  });
};

const savePanoramic = async (
  imageId: string,
  panoramic: Float32Array<ArrayBuffer>,
  panoramicDimensions: NumberPair,
  spacing: number,
  layerSpacing: number
) => {
  const [width, height] = panoramicDimensions;
  const { windowCenter, windowWidth } = metaData.get('voiLutModule', imageId);
  const { bitsStored } = metaData.get('imagePixelModule', imageId);
  const { seriesInstanceUID, studyInstanceUID } = metaData.get('generalSeriesModule', imageId);

  const datasetOptions = {
    SeriesInstanceUID: seriesInstanceUID + '.panoramic',
    StudyInstanceUID: studyInstanceUID,
    PixelSpacing: [layerSpacing, spacing] as NumberPair,
  };
  const pngBuf = pixelDataToPngBuffer(panoramic, bitsStored, windowCenter[0], windowWidth[0]);
  const canvas = await pngBufferToCanvas(pngBuf, width, height);
  const dataset = await createDataset(canvas, datasetOptions);
  const datasets = new Array(width).fill(dataset);
  DicomMetadataStore.addInstances(datasets);
};

const saveDentascans = async (
  imageId: string,
  dentascans: Float32Array<ArrayBuffer>[],
  dentascanDimensions: NumberPair,
  spacing: number,
  layerSpacing: number
) => {
  const [width, height] = dentascanDimensions;
  const { windowCenter, windowWidth } = metaData.get('voiLutModule', imageId);
  const { bitsStored } = metaData.get('imagePixelModule', imageId);
  const { seriesInstanceUID, studyInstanceUID } = metaData.get('generalSeriesModule', imageId);
  const SOPInstanceUID = Math.random().toString(36).substring(2, 10);

  const datasets = await Promise.all(
    dentascans.map(async (dentascan, i) => {
      const datasetOptions = {
        SeriesInstanceUID: seriesInstanceUID + '.dentascan',
        StudyInstanceUID: studyInstanceUID,
        SOPInstanceUID: `${SOPInstanceUID}.${i + 1}`,
        InstanceNumber: i + 1,
        ImagePositionPatient: [0, 0, i * spacing],
        PixelSpacing: [layerSpacing, spacing] as NumberPair,
        SliceThickness: spacing,
      };
      const pngBuf = pixelDataToPngBuffer(dentascan, bitsStored, windowCenter[0], windowWidth[0]);
      const canvas = await pngBufferToCanvas(pngBuf, width, height, true);
      const dataset = await createDataset(canvas, datasetOptions);
      return dataset;
    })
  );
  DicomMetadataStore.addInstances(datasets);
};

const getControlPoints = (
  displaySetUID: string,
  imageData: vtkImageData,
  bounds: Bounds,
  servicesManager: AppTypes.ServicesManager
): { x: number; y: number }[] => {
  const { measurementService } = servicesManager.services;

  const measurements = measurementService.getMeasurements();
  const { points: controlPointsInViewport }: { points: Point3[] } = measurements.find(
    m =>
      m.toolName === 'LineSegment' &&
      m.metadata.handmade &&
      m.displaySetInstanceUID === displaySetUID
  );
  if (!controlPointsInViewport) {
    return [];
  }

  const { minX, maxX, minY, maxY } = bounds;
  // Regenerate points from annoted points in viewport
  const controlPointsInVolume = controlPointsInViewport.map(point => {
    let [x, y, _] = imageData.worldToIndex(point) as Point3;
    x = Math.min(Math.max(Math.round(x), minX), maxX);
    y = Math.min(Math.max(Math.round(y), minY), maxY);
    return { x, y };
  });
  controlPointsInVolume.sort((p1, p2) => p1.x - p2.x);

  return controlPointsInVolume;
};

const createOrRegenerateControlPoints = (
  displaySetUID: string,
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  imageData: vtkImageData,
  [minLayer, maxLayer]: NumberPair,
  spacing: number,
  servicesManager: AppTypes.ServicesManager,
  antiAliasing: boolean = false
): [Points, NumberPair] => {
  const { panoramicService } = servicesManager.services;

  const panoramicState = panoramicService.getPanoramicState(displaySetUID);

  let controlPoints: { x: number; y: number }[];
  if (panoramicState) {
    const [layerWidth, layerHeight, _] = dimensions;
    const axialBounds: Bounds = { minX: 0, maxX: layerWidth - 1, minY: 0, maxY: layerHeight - 1 };
    controlPoints = getControlPoints(displaySetUID, imageData, axialBounds, servicesManager);
  }
  let points: Points, minMaxTissueLayer: NumberPair;
  if (!controlPoints?.length) {
    // Initialize control points
    [points, minMaxTissueLayer] = createControlPoints(
      scalarData,
      dimensions,
      [minLayer, maxLayer],
      spacing,
      antiAliasing
    );
  } else {
    points = regenerateControlPoints(controlPoints, dimensions, spacing, antiAliasing);
    minMaxTissueLayer = panoramicState.minMaxTissueLayer;
  }

  return [points, minMaxTissueLayer];
};

