const updatePanoramic = (
  minMaxTissueLayer: NumberPair,
  dentascanWidth: number,
  points: Points,
  panoramic: Float32Array<ArrayBuffer>,
  servicesManager: AppTypes.ServicesManager,
  isFromDatabase: boolean = false
) => {
  const { cornerstoneViewportService, databaseService, panoramicService } =
    servicesManager.services;

  const { displaySetInstanceUID, volume } = cornerstoneViewportService
    .getViewportInfo('axial')
    .getViewportData().data[0] as VolumeData;
  const voxelManager = volume.voxelManager as IVoxelManager<number>;
  const scalarData = voxelManager.getCompleteScalarDataArray();
  const { dimensions, imageData } = volume;
  const spacing: number = Math.min(...volume.spacing);
  const layerSpacing: number = volume.spacing[2];

  const minMaxLayer: [number, number] = getMinMaxLayer(scalarData, dimensions);
  const [minLayer, maxLayer] = minMaxLayer;
  const nbLayers = maxLayer - minLayer;

  const [dentascans, validMasks] = computeDentascansNoAliasing(
    scalarData,
    dimensions,
    minMaxLayer,
    dentascanWidth,
    points
  );

  const panoramicState = panoramicService.getPanoramicState(displaySetInstanceUID);
  const annotationUIDs = generateAnnotations(
    panoramicState,
    imageData,
    points,
    minMaxLayer,
    servicesManager
  );
  if (panoramicState) {
    deletePanoramic(servicesManager);
  }
  panoramicService.setDentascansReady(displaySetInstanceUID, false);

  if (!isFromDatabase) {
    databaseService.modifyAnalyzePanoramic(panoramic);
    databaseService.modifyAnalyzeMetadata({
      dentascan_thickness: dentascanWidth,
      min_max_tissue_layer: minMaxTissueLayer,
      points,
    });
  }

  const imageId = panoramicService._getImageId(displaySetInstanceUID);
  const panoramicWidth = dentascans.length;
  savePanoramic(imageId, panoramic, [panoramicWidth, nbLayers], spacing, layerSpacing);
  saveDentascans(imageId, dentascans, [dentascanWidth, nbLayers], spacing, layerSpacing).then(
    () => {
      panoramicService.setDentascansReady(displaySetInstanceUID, true);
    }
  );

  panoramicService.setPanoramicState(displaySetInstanceUID, {
    ...panoramicState,
    implants: panoramicState?.implants ?? [],
    annotationUIDs,
    minMaxLayer,
    minMaxTissueLayer,
    minPoints: points.outerPoints,
    normals: points.normals,
    dentascans,
    dentascansDimensions: [panoramicWidth, dentascanWidth, nbLayers],
  });
};

export { generatePanoramic, updatePanoramic };
