import { NumberPair, XYXPos } from 'extensions/cornerstone/src/types/Panoramic';
import { blurPanoramic } from './computePanoramicUtils';
import { getParameters } from './cbctUtils';

// Control points that can be changed in front will be re-used to compute
// a new dental curve thus a new panoramic
const createPanoramicFull = (
  dentascans: Float32Array<ArrayBuffer>[],
  validMasks: boolean[][],
  nbLayers: number,
  spacing: number,
  dentalCurvesPointsXY: XYXPos[],
  dentalCurvesStep: number = 1,
  axialCurvesStep: number = 1
) => {
  // This promise take a base point and an offset
  // It fills panoramicArray from basePoint to next basePoint
  // Offset as explained earlier is the starting width of the base point
  // TODO

  // Init panoramic array
  const panoramicWidth: number = dentascans.length;
  const panoramic = new Float32Array(panoramicWidth * nbLayers).fill(-1000);
  const nbDentalCurves: number = Math.floor(panoramicWidth / dentalCurvesStep);

  const { dentascanWidth, dentalCurveWidth } = getParameters(spacing);
  // From start of base point to start of other base point, incremented by vector direction between those two points
  for (let idx = 0; idx < panoramicWidth; idx++) {
    const i: number = Math.floor(idx / dentalCurvesStep);
    const dentascanIndex: number = panoramicWidth - idx - 1;
    const dentascan: Float32Array<ArrayBuffer> = dentascans[dentascanIndex];
    const validMask: boolean[] = validMasks[dentascanIndex];

    //const coordinatesSlice = axialCurvesPoints.slice(idx * nbAxialCurves, (idx + 1) * nbAxialCurves).filter(value => value);
    //const dentalCurve = polynomialLSF(coordinatesSlice, 3);
    for (let layer = 0; layer < nbLayers; layer++) {
      const l: number = Math.floor(layer / axialCurvesStep);
      const { x, y, xpos } = dentalCurvesPointsXY[l * nbDentalCurves + i];
      const valuesAlongNormal: number[] = [];

      // Get values of point along normal between min and max
      const kMin: number = Math.floor(xpos - dentalCurveWidth / 2);
      const kMax: number = kMin + dentalCurveWidth;
      for (let k = kMin; k < kMax; k++) {
        // TODO Values are now picked from the dentascans instead of being picked from the volume, so that anti-aliasing is applied.

        if (!validMask[k]) {
          continue;
        }

        const scalarValue: number = dentascan[layer * dentascanWidth + k];
        const scalarValueNormalized: number = Math.max(Math.min(Math.floor((scalarValue + 1000) / 16) / 255, 1), 0);
        //let scalarValue = Math.floor((scalarData[layer * layerSize + yk * layerWidth + xk] + 1000) / 16) / 255;
        //let scalarValue = (scalarData[layer * layerSize + yk * layerWidth + xk] + 1000) / 16;
        //if (scalarValue >= 50) {
        //valuesAlongNormal.push(Math.exp(scalarValue / S));

        // The following formula computes the factor depending on dental curve thickness, when scalarValue
        // equals 1, as empiric tests showed factor 0.15 was the best for dental curve thickness of 40
        const factor: number = 1 - Math.pow(0.85, 40 / dentalCurveWidth);
        valuesAlongNormal.push(1 - factor * Math.pow(scalarValueNormalized, 3));
      }

      // Add mean of all values as value in panoramic result
      // TODO
      const absorption: number = valuesAlongNormal.reduce((a, b) => a * b, 1);
      //let mean = valuesAlongNormal.reduce((a, b) => a + b, 0) / valuesAlongNormal.length;
      //const max = getMax(valuesAlongNormal);
      //panoramic[panoramicWidth * (nbLayers - layer - 1) + idx] = S * Math.log(mean) * 16 - 1000;
      panoramic[panoramicWidth * (nbLayers - layer - 1) + idx] = (1 - absorption) * 255 * 16 - 1000;
    }
  }

  return panoramic;
};

const panoramicPostProcessing = (
  panoramic: Float32Array<ArrayBuffer>,
  [width, height]: NumberPair
): Float32Array<ArrayBuffer> => {
  const alpha = 0.9;
  const gImage: Float32Array<ArrayBuffer> = blurPanoramic(panoramic, width, height);
  const panoramicProcessed: Float32Array<ArrayBuffer> = new Float32Array(panoramic.length);
  for (let i = 0; i < panoramic.length; i++) {
    panoramicProcessed[i] = alpha * panoramic[i] + (1 - alpha) * (panoramic[i] - gImage[i]);
  }

  return panoramicProcessed;
};

export { createPanoramicFull, panoramicPostProcessing };
