import { v4 as uuidv4 } from 'uuid';
import { ChunkReassembler } from './chunkReassembler';
import {
  ChunkEnvelope,
  DbAuthResponse,
  DbMessageType,
  DbRequest,
  DbResponse,
  DbServerEvent,
  DbServerEventType,
  StreamAckControl,
  StreamCompleteControl,
  StreamControlMessage,
  StreamErrorControl,
  StreamOpenControl,
} from './database';
import axios from 'axios';

const REQUEST_TIMEOUT_MS = 30_000;
const LARGE_PAYLOAD_REQUEST_TIMEOUT_MS = 120_000;
/** Session creation + offer POST + answer retrieval (inline or polling). */
const CONNECT_SIGNALING_PHASE_TIMEOUT_MS = 30_000;
/** After answer: DTLS + SCTP + data channel `open` + host auth message. */
const CONNECT_POST_ANSWER_TIMEOUT_MS = 11_000;
/** After local data channel opens: host may show a manual approval dialog. */
const CONNECT_AUTH_RESPONSE_TIMEOUT_MS = 12_000;
const ICE_GATHERING_TIMEOUT_MS = 5_000;
/** Reachability probe: session creation, offer POST, answer retrieval — ICE gathering at both ends. */
const PROBE_SIGNALLING_TIMEOUT_MS = 8_000;
/** After the answer is applied: ICE connectivity checks + DTLS. */
const PROBE_POST_ANSWER_TIMEOUT_MS = 6_000;
/** A probe is throwaway, so it waits less for local gathering than a real connect does. */
const PROBE_ICE_GATHERING_TIMEOUT_MS = 3_000;
/**
 * How long a peer connection may sit in `disconnected` before we treat the link as lost.
 *
 * `disconnected` is a recoverable state: ICE can return to `connected` on its own, with no
 * renegotiation. Chromium and Gecko go to `failed` on consent failure so they rarely dwell there,
 * but WebKit emits it readily — including as a brief blip just after a connection settles — and
 * recovers. Tearing down on sight is therefore an infinite reconnect cycle on Safari, where every
 * attempt connects and is then killed by the next blip. Waiting it out costs nothing on the
 * browsers that do go straight to `failed`, since that stays terminal below.
 */
const CONNECTION_DISCONNECTED_GRACE_MS = 6_000;
const ANSWER_POLL_MIN_INTERVAL_MS = 150;
const ANSWER_POLL_MAX_INTERVAL_MS = 400;
/** Growth applied to the poll interval each attempt, and the ceiling it grows to. */
const ANSWER_POLL_BACKOFF_FACTOR = 1.5;
const ANSWER_POLL_MAX_BACKOFF_MS = 2_000;
/**
 * No STUN/TURN: the host is reachable only from the practice network or a VPN into it, so host
 * candidates are all that is needed and gathering completes almost immediately. Note this is not
 * what enforces that boundary — removing traversal assistance does not stop a directly routable
 * peer. The host filters candidates to private address space for that (see
 * `app/src/backend/webrtc/iceCandidateFilter.ts`).
 */
const DEFAULT_WEBRTC_ICE_SERVERS: RTCIceServer[] = [];
/**
 * Cloud signalling API origin. Session create already used an absolute URL; offer/poll used
 * relative paths, which from the OHIF iframe (`http://127.0.0.1:<port>/ohif/`) hit the local
 * static server instead of the cloud — so the host never saw the offer and connect timed out.
 * Keep every signalling call on this origin.
 */
const SIGNALLING_API_BASE = 'https://beta.radiann.eu';
const DATA_CHANNEL_MAX_CHUNK_BYTES = 12 * 1024;
const DATA_CHANNEL_BINARY_CHUNK_BYTES = DATA_CHANNEL_MAX_CHUNK_BYTES;
const DATA_CHANNEL_BUFFER_HIGH_WATER_MARK = 256 * 1024;
const DATA_CHANNEL_BUFFER_LOW_WATER_MARK = 64 * 1024;
const STREAM_ACK_WINDOW_BYTES = 4 * 1024 * 1024;
const STREAM_TRANSFER_TIMEOUT_MS = 30 * 60 * 1000;
const CHUNK_REASSEMBLY_TIMEOUT_MS = 30_000;

/**
 * Electron forwards renderer console lines without formatting extra object args,
 * so `console.info("msg", obj)` becomes `[object Object]`.  Emit one string line instead.
 */
const stringifyTransportLogDetail = (detail: unknown): string => {
  if (detail === undefined) {
    return '';
  }
  try {
    return JSON.stringify(detail, (_key, value: unknown) => {
      if (value instanceof Error) {
        return { message: value.message, name: value.name, stack: value.stack };
      }
      return value;
    });
  } catch {
    return String(detail);
  }
};

const transportLog = (
  level: 'info' | 'warn' | 'error',
  message: string,
  detail?: unknown
): void => {
  const line = detail === undefined ? message : `${message} ${stringifyTransportLogDetail(detail)}`;
  if (level === 'warn') {
    console.warn(line);
  } else if (level === 'error') {
    console.error(line);
  } else {
    console.info(line);
  }
};

/**
 * Removes `a=end-of-candidates` from an offer before it is signalled.
 *
 * The werift host cannot resolve the mDNS names browsers use for host candidates, so it relies on
 * peer-reflexive discovery — learning our address from the connectivity checks we send it. This
 * line tells it the candidate list is final, at which point it sees an empty list and fails ICE
 * negotiation immediately, before any check arrives. Firefox emits it and Chrome does not, which is
 * why connecting only ever worked in Chrome.
 *
 * The host strips this as well; doing it here too means a browser that needs the fix is not waiting
 * on a host update to get it.
 */
const stripEndOfCandidates = (sdp: string): string =>
  sdp
    .split('\n')
    .filter(line => !line.startsWith('a=end-of-candidates'))
    .join('\n');

interface PendingRequest {
  resolve: (value: unknown) => void;
  reject: (reason: Error) => void;
  timer: ReturnType<typeof setTimeout>;
}

interface PendingUploadTransfer {
  resolve: () => void;
  reject: (reason: Error) => void;
  totalBytes: number;
  ackedBytes: number;
  timer: ReturnType<typeof setTimeout>;
}

interface IncomingTransfer {
  resolve: (result: Blob) => void;
  reject: (reason: Error) => void;
  totalBytes: number;
  receivedBytes: number;
  mimeType?: string;
  chunks: Uint8Array[];
  timer: ReturnType<typeof setTimeout>;
}

type ConnectionChangeCallback = (connected: boolean) => void;
type WaitingForApprovalCallback = (waiting: boolean) => void;
type ReconnectingChangeCallback = (reconnecting: boolean) => void;
type ServerEventCallback = (payload: unknown) => void;

class DatabaseTransport {
  private textDecoder = new TextDecoder();
  private pc: RTCPeerConnection | null = null;
  private channel: RTCDataChannel | null = null;
  private activeConnectPromise: Promise<void> | null = null;
  private activeConnectTarget: string | null = null;
  private activeConnectReject: ((error: Error) => void) | null = null;
  private chunkReassembler = new ChunkReassembler(CHUNK_REASSEMBLY_TIMEOUT_MS);
  private pendingRequests = new Map<string, PendingRequest>();
  private pendingUploadTransfers = new Map<string, PendingUploadTransfer>();
  private incomingTransfers = new Map<string, IncomingTransfer>();
  private pendingIncomingTransferPromises = new Map<string, Promise<Blob>>();
  private activeIncomingTransferId: string | null = null;
  // Binary frames carry no transfer id, so only one transfer per direction can be in flight:
  // whoever is receiving routes every binary frame to whichever transfer is currently open.
  // Serialising here is what keeps that true. Uploads and downloads are independent directions,
  // hence two queues.
  private uploadQueue: Promise<unknown> = Promise.resolve();
  private downloadQueue: Promise<unknown> = Promise.resolve();
  private _connected = false;
  private _waitingForApproval = false;
  private _reconnecting = false;
  private shouldAutoReconnect = false;
  private reconnectAttempt = 0;
  private reconnectTimer: ReturnType<typeof setTimeout> | null = null;
  private lastServerUrl: string | null = null;
  private lastDiscoveryUuid: string | null = null;
  private signallingAccessToken: string | null = null;
  private connectionChangeListeners: ConnectionChangeCallback[] = [];
  private waitingForApprovalListeners: WaitingForApprovalCallback[] = [];
  private reconnectingChangeListeners: ReconnectingChangeCallback[] = [];
  private serverEventListeners = new Map<DbServerEventType, ServerEventCallback[]>();

  isConnected(): boolean {
    return this._connected && this.channel?.readyState === 'open';
  }

  get waitingForApproval(): boolean {
    return this._waitingForApproval;
  }

  get reconnecting(): boolean {
    return this._reconnecting;
  }

  onConnectionChange(cb: ConnectionChangeCallback): () => void {
    this.connectionChangeListeners.push(cb);
    return () => {
      this.connectionChangeListeners = this.connectionChangeListeners.filter(fn => fn !== cb);
    };
  }

  onWaitingForApprovalChange(cb: WaitingForApprovalCallback): () => void {
    this.waitingForApprovalListeners.push(cb);
    return () => {
      this.waitingForApprovalListeners = this.waitingForApprovalListeners.filter(fn => fn !== cb);
    };
  }

  onReconnectingChange(cb: ReconnectingChangeCallback): () => void {
    this.reconnectingChangeListeners.push(cb);
    return () => {
      this.reconnectingChangeListeners = this.reconnectingChangeListeners.filter(fn => fn !== cb);
    };
  }

  onServerEvent(event: DbServerEventType, cb: ServerEventCallback): () => void {
    const listeners = this.serverEventListeners.get(event) ?? [];
    this.serverEventListeners.set(event, [...listeners, cb]);

    return () => {
      const current = this.serverEventListeners.get(event) ?? [];
      this.serverEventListeners.set(
        event,
        current.filter(fn => fn !== cb)
      );
    };
  }

  /**
   * Notifies subscribers, isolating each one.
   *
   * These fire from the middle of teardown, so a subscriber that throws used to take the rest of
   * the teardown with it — including the `scheduleReconnect` at the end of `handleConnectionLost`,
   * which strands the UI on "reconnecting" with no retry ever queued. A broken subscriber must not
   * be able to disable reconnection.
   */
  private notifyListeners<T>(listeners: ((value: T) => void)[], value: T, label: string): void {
    for (const cb of listeners) {
      try {
        cb(value);
      } catch (error) {
        transportLog('error', '[dbTransport] listener threw', { label, error });
      }
    }
  }

  private setConnected(connected: boolean): void {
    if (this._connected === connected) return;
    this._connected = connected;
    this.notifyListeners(this.connectionChangeListeners, connected, 'connectionChange');
  }

  private setWaitingForApproval(waiting: boolean): void {
    if (this._waitingForApproval === waiting) return;
    this._waitingForApproval = waiting;
    this.notifyListeners(this.waitingForApprovalListeners, waiting, 'waitingForApprovalChange');
  }

  private setReconnecting(reconnecting: boolean): void {
    if (this._reconnecting === reconnecting) return;
    this._reconnecting = reconnecting;
    this.notifyListeners(this.reconnectingChangeListeners, reconnecting, 'reconnectingChange');
  }

  private clearReconnectTimer(): void {
    if (!this.reconnectTimer) return;
    clearTimeout(this.reconnectTimer);
    this.reconnectTimer = null;
  }

  private scheduleReconnect(): void {
    if (
      !this.shouldAutoReconnect ||
      !this.lastServerUrl ||
      this.reconnectTimer ||
      this.isConnected()
    ) {
      return;
    }

    this.setReconnecting(true);
    const delay = Math.min(30_000, 1_000 * 2 ** this.reconnectAttempt);
    this.reconnectAttempt += 1;
    transportLog('info', '[dbTransport] reconnect scheduled', {
      target: this.lastServerUrl,
      attempt: this.reconnectAttempt,
      delayMs: delay,
    });

    this.reconnectTimer = setTimeout(() => {
      this.reconnectTimer = null;
      // Keyed off the outcome rather than off rejection alone: an attempt can also *resolve*
      // without leaving us connected — it is deduplicated onto an already-settled attempt to
      // the same target. Retrying whenever we are still disconnected means no settle path can
      // silently end the loop and strand the UI on "reconnecting" forever.
      //
      // A connect can fail before any peer connection exists (the signalling/ICE phase, which
      // is exactly what happens right after a host restart while the host's cloud-signalling
      // subscription is still coming up); no `onclose`/`onconnectionstatechange` fires then, so
      // this is the only thing continuing the loop. When it fails *after* a channel opened,
      // `onclose` schedules too, but the `reconnectTimer`/`isConnected` guard keeps that idempotent.
      const continueLoop = (): void => {
        if (!this.isConnected()) {
          this.scheduleReconnect();
        }
      };
      void this.connect(this.lastServerUrl!, undefined, this.lastDiscoveryUuid ?? undefined).then(
        continueLoop,
        continueLoop
      );
    }, delay);
  }

  /**
   * The host announced it is restarting (e.g. after a database move/load) and is about to
   * drop us. Tear the current connection down now — so `isConnected()` flips to false and
   * the UI shows "reconnecting" — and schedule a fresh attempt from the base backoff. Without
   * this we'd keep a dead-but-"open" channel until ICE-failure detection fires, which over a
   * LAN with no STUN/TURN can take tens of seconds or never happen.
   */
  private handleHostRestartSignal(): void {
    if (!this.shouldAutoReconnect || !this.lastServerUrl) {
      return;
    }
    transportLog('info', '[dbTransport] host restart signal received; reconnecting', {
      target: this.lastServerUrl,
    });
    this.reconnectAttempt = 0;
    this.disconnectCurrentConnection();
    this.scheduleReconnect();
  }

  /**
   * The peer went away — the data channel closed, or the peer connection failed. Drops the dead
   * objects, flips the UI to disconnected, and starts the retry loop.
   *
   * Also aborts an in-flight connect attempt. When the link dies *during* a connect (the host
   * dropping us while we wait on its auth response, say) nothing else settles that attempt until
   * its own phase timeout fires, and an unsettled attempt makes every retry a no-op that is
   * deduplicated onto it.
   */
  private handleConnectionLost(): void {
    // Detach before closing. WebKit dispatches `connectionstatechange` synchronously from
    // `close()` where Chromium queues it as a task, so closing first would re-enter this
    // method through its own handler while the fields still pointed at the dying connection.
    const channel = this.channel;
    const pc = this.pc;
    this.channel = null;
    this.pc = null;

    // `scheduleReconnect` runs from a `finally` so that nothing above it — a close that throws,
    // a subscriber that throws — can leave the link dead with no retry queued.
    try {
      this.setWaitingForApproval(false);
      this.rejectAllPending('Connection closed');
      try {
        channel?.close();
        pc?.close();
      } catch {
        // Ignore close errors while dropping an already-dead connection.
      }
      this.setConnected(false);
      this.activeConnectReject?.(new Error('Connection closed'));
    } finally {
      this.scheduleReconnect();
    }
  }

  private disconnectCurrentConnection(): void {
    this.rejectAllPending('Disconnected');
    this.rejectAllPendingTransfers('Disconnected');
    this.chunkReassembler.clearAll();
    // Detached before closing for the same reason as `handleConnectionLost`: on WebKit the
    // close dispatches its state change synchronously, straight back into our handlers.
    const channel = this.channel;
    const pc = this.pc;
    this.channel = null;
    this.pc = null;
    channel?.close();
    pc?.close();
    this.activeConnectPromise = null;
    this.activeConnectTarget = null;
    this.setWaitingForApproval(false);
    this.setConnected(false);
    // Abort an in-flight connect attempt so a cancel/teardown rejects the awaiting
    // caller right away. No-op once the attempt has already settled (e.g. when an
    // internal failure path called rejectConnect before tearing the connection down).
    this.activeConnectReject?.(new Error('Disconnected'));
  }

  private normalizeIceServersFromApi(raw: unknown): RTCIceServer[] {
    if (!Array.isArray(raw)) {
      return [];
    }
    const out: RTCIceServer[] = [];
    for (const item of raw) {
      if (!item || typeof item !== 'object') {
        continue;
      }
      const o = item as Record<string, unknown>;
      const urls = o.urls;
      if (typeof urls === 'string') {
        out.push({ urls });
      } else if (Array.isArray(urls) && urls.length > 0 && urls.every(u => typeof u === 'string')) {
        out.push({ urls: urls as string[] });
      }
    }
    return out;
  }

  private async createSignallingSession(
    targetUrl: string,
    discoveryUuid: string
  ): Promise<{ sessionId: string; rtcConfiguration: RTCConfiguration }> {
    let targetUrlForSignalling = targetUrl;
    try {
      const parsed = new URL(targetUrl);
      parsed.searchParams.set('discovery_uuid', discoveryUuid);
      targetUrlForSignalling = parsed.toString();
    } catch {
      // Keep original URL if parsing fails unexpectedly.
    }
    const headers = this.signallingAccessToken
      ? {
          Authorization: 'Bearer ' + this.signallingAccessToken,
          'Content-Type': 'application/json',
        }
      : undefined;
    const response = await axios.post(
      `${SIGNALLING_API_BASE}/api/v1/discovery/webrtc/session/`,
      { target_url: targetUrlForSignalling, discovery_uuid: discoveryUuid },
      { headers }
    );

    const data = response.data as Record<string, unknown>;
    const pk = data.pk ?? data.id ?? data.sessionId ?? data.session_id;
    if (typeof pk !== 'string' && typeof pk !== 'number') {
      throw new Error('Missing signalling session id');
    }
    const fromApi = this.normalizeIceServersFromApi(data.iceServers ?? data.ice_servers);
    const iceServers = fromApi.length > 0 ? fromApi : DEFAULT_WEBRTC_ICE_SERVERS;
    return {
      sessionId: String(pk),
      rtcConfiguration: {
        iceServers,
        bundlePolicy: 'max-bundle',
        rtcpMuxPolicy: 'require',
      },
    };
  }

  private extractAnswerSdp(message: Record<string, unknown>): string | null {
    const direct = message.sdpAnswer ?? message.sdp_answer ?? message.answer;
    if (typeof direct === 'string') {
      return direct;
    }

    const payload = message.payload;
    if (payload && typeof payload === 'object') {
      const nested = payload as Record<string, unknown>;
      const nestedSdp = nested.sdpAnswer ?? nested.sdp_answer ?? nested.answer;
      if (typeof nestedSdp === 'string') {
        return nestedSdp;
      }
    }

    return null;
  }

  private bufferToBase64(buffer: ArrayBuffer): string {
    const bytes = new Uint8Array(buffer);
    let binary = '';
    const chunkSize = 0x8000;

    for (let i = 0; i < bytes.length; i += chunkSize) {
      const chunk = bytes.subarray(i, i + chunkSize);
      binary += String.fromCharCode(...chunk);
    }

    return btoa(binary);
  }

  private getRequestTimeoutMs(type: DbMessageType): number {
    switch (type) {
      case 'addImage':
      case 'getImageByHash':
      case 'getImageContentById':
      case 'getImageFullContentById':
        return LARGE_PAYLOAD_REQUEST_TIMEOUT_MS;
      default:
        return REQUEST_TIMEOUT_MS;
    }
  }

  private splitStringByUtf8ByteLength(raw: string, maxBytes: number): string[] {
    if (new TextEncoder().encode(raw).length <= maxBytes) {
      return [raw];
    }

    const chunks: string[] = [];
    let start = 0;

    while (start < raw.length) {
      let end = Math.min(raw.length, start + maxBytes);
      let chunk = raw.slice(start, end);

      while (chunk.length > 1 && new TextEncoder().encode(chunk).length > maxBytes) {
        end -= 1;
        chunk = raw.slice(start, end);
      }

      if (!chunk) {
        throw new Error('Unable to split payload for WebRTC transport');
      }

      chunks.push(chunk);
      start = end;
    }

    return chunks;
  }

  private waitForBufferedAmountDrain(): Promise<void> {
    if (!this.channel) {
      return Promise.reject(new Error('DataChannel not connected'));
    }

    const channel = this.channel;
    if (
      typeof channel.bufferedAmount !== 'number' ||
      channel.bufferedAmount <= DATA_CHANNEL_BUFFER_HIGH_WATER_MARK
    ) {
      return Promise.resolve();
    }

    return new Promise<void>((resolve, reject) => {
      const timer = setTimeout(() => {
        cleanup();
        reject(new Error('DataChannel buffer did not drain'));
      }, 10_000);

      const poll = setInterval(() => {
        if (!this.channel || this.channel !== channel || channel.readyState !== 'open') {
          cleanup();
          reject(new Error('DataChannel closed while waiting for drain'));
          return;
        }
        if (channel.bufferedAmount <= DATA_CHANNEL_BUFFER_LOW_WATER_MARK) {
          cleanup();
          resolve();
        }
      }, 25);

      const cleanup = () => {
        clearTimeout(timer);
        clearInterval(poll);
      };
    });
  }

  /**
   * Runs `task` after every previously queued task on the same direction has settled.
   *
   * The stored chain swallows failures so one failed transfer cannot wedge the queue, while the
   * returned promise still surfaces them to the caller.
   */
  private enqueueTransfer<T>(direction: 'upload' | 'download', task: () => Promise<T>): Promise<T> {
    const previous = direction === 'upload' ? this.uploadQueue : this.downloadQueue;
    const next = previous.then(task, task);
    const settled = next.then(
      () => undefined,
      () => undefined
    );
    if (direction === 'upload') {
      this.uploadQueue = settled;
    } else {
      this.downloadQueue = settled;
    }
    return next;
  }

  private createTransferTimeout(callback: () => void): ReturnType<typeof setTimeout> {
    return setTimeout(callback, STREAM_TRANSFER_TIMEOUT_MS);
  }

  private refreshUploadTransferTimeout(transferId: string): void {
    const transfer = this.pendingUploadTransfers.get(transferId);
    if (!transfer) {
      return;
    }
    clearTimeout(transfer.timer);
    transfer.timer = this.createTransferTimeout(() => {
      this.pendingUploadTransfers.delete(transferId);
      transfer.reject(new Error(`Stream transfer timeout: ${transferId}`));
    });
  }

  private refreshIncomingTransferTimeout(transferId: string): void {
    const transfer = this.incomingTransfers.get(transferId);
    if (!transfer) {
      return;
    }
    clearTimeout(transfer.timer);
    transfer.timer = this.createTransferTimeout(() => {
      this.incomingTransfers.delete(transferId);
      if (this.activeIncomingTransferId === transferId) {
        this.activeIncomingTransferId = null;
      }
      transfer.reject(new Error(`Incoming stream timeout: ${transferId}`));
    });
  }

  private typedArrayToBufferJson(view: ArrayBufferView): { type: 'Buffer'; data: number[] } {
    const bytes = new Uint8Array(view.buffer, view.byteOffset, view.byteLength);
    return { type: 'Buffer', data: Array.from(bytes) };
  }

  private convertArrayBuffersToBase64(input: unknown): unknown {
    if (input instanceof ArrayBuffer) {
      return this.bufferToBase64(input);
    }

    if (ArrayBuffer.isView(input)) {
      return this.typedArrayToBufferJson(input);
    }

    if (Array.isArray(input)) {
      return input.map(value => this.convertArrayBuffersToBase64(value));
    }

    if (input && typeof input === 'object') {
      const result: Record<string, unknown> = {};
      for (const [key, value] of Object.entries(input as Record<string, unknown>)) {
        result[key] = this.convertArrayBuffersToBase64(value);
      }
      return result;
    }

    return input;
  }

  /**
   * Recognises a text frame that arrived as bytes, without mistaking image data for one.
   *
   * Being valid JSON is not enough: a downloaded file whose bytes happen to decode as JSON would
   * be pulled out of its own transfer and handled as a message. Only frames shaped like our
   * protocol — a stream control, a chunk envelope, a response carrying an id, or a server event —
   * are treated as text.
   */
  private tryParseJsonTextFromBinary(data: Uint8Array): string | null {
    try {
      const candidate = this.textDecoder.decode(data);
      if (!candidate.trimStart().startsWith('{')) {
        return null;
      }
      const parsed: unknown = JSON.parse(candidate);
      if (!parsed || typeof parsed !== 'object') {
        return null;
      }
      if (this.isStreamControlMessage(parsed) || ChunkReassembler.isChunkEnvelope(parsed)) {
        return candidate;
      }
      const message = parsed as { id?: unknown; event?: unknown };
      return typeof message.id === 'string' || typeof message.event === 'string' ? candidate : null;
    } catch {
      return null;
    }
  }

  private async waitForIceGatheringComplete(
    pc: RTCPeerConnection,
    timeoutMs: number
  ): Promise<boolean> {
    if (pc.iceGatheringState === 'complete') {
      return true;
    }

    return await new Promise<boolean>(resolve => {
      const timeout = setTimeout(() => {
        cleanup();
        resolve(false);
      }, timeoutMs);

      const onIceGatheringStateChange = () => {
        if (pc.iceGatheringState === 'complete') {
          cleanup();
          resolve(true);
        }
      };

      const cleanup = () => {
        clearTimeout(timeout);
        pc.removeEventListener('icegatheringstatechange', onIceGatheringStateChange);
      };

      pc.addEventListener('icegatheringstatechange', onIceGatheringStateChange);
    });
  }

  private extractSignallingStatus(message: Record<string, unknown>): string | null {
    const direct = message.status;
    if (typeof direct === 'string') {
      return direct.toLowerCase();
    }
    const payload = message.payload;
    if (payload && typeof payload === 'object') {
      const nested = (payload as Record<string, unknown>).status;
      if (typeof nested === 'string') {
        return nested.toLowerCase();
      }
    }
    return null;
  }

  private async pollSessionForAnswerSdp(sessionPath: string, deadlineTs: number): Promise<string> {
    let attempt = 0;
    while (Date.now() < deadlineTs) {
      const headers = this.signallingAccessToken
        ? { Authorization: 'Bearer ' + this.signallingAccessToken }
        : undefined;
      const response = await axios.get(`${SIGNALLING_API_BASE}/${sessionPath}/`, { headers });
      const json = response.data as Record<string, unknown>;
      const sdpAnswer = this.extractAnswerSdp(json);
      if (sdpAnswer) {
        return sdpAnswer;
      }

      const status = this.extractSignallingStatus(json);
      if (status === 'failed' || status === 'error') {
        throw new Error(`Signalling session failed (${status})`);
      }

      // Poll fast at first, since the host normally answers within a second, then back off.
      // At a flat interval a connect that ends up timing out costs the backend upwards of a
      // hundred requests; backing off keeps the common case as quick as it was while making a
      // stalled attempt far cheaper.
      const jitterMs =
        ANSWER_POLL_MIN_INTERVAL_MS +
        Math.floor(Math.random() * (ANSWER_POLL_MAX_INTERVAL_MS - ANSWER_POLL_MIN_INTERVAL_MS + 1));
      const backedOffMs = Math.min(
        ANSWER_POLL_MAX_BACKOFF_MS,
        Math.round(jitterMs * ANSWER_POLL_BACKOFF_FACTOR ** attempt)
      );
      attempt += 1;
      await new Promise<void>(resolve => setTimeout(resolve, backedOffMs));
    }

    throw new Error('WebRTC connection timeout');
  }

  async connect(serverUrl: string, accessToken?: string, discoveryUuid?: string): Promise<void> {
    const normalizedUrl = serverUrl.trim().replace(/\/+$/, '');
    const providedDiscoveryUuid =
      typeof discoveryUuid === 'string' && discoveryUuid.trim().length > 0
        ? discoveryUuid.trim()
        : null;
    const effectiveDiscoveryUuid = providedDiscoveryUuid ?? this.lastDiscoveryUuid;
    if (typeof accessToken === 'string' && accessToken.length > 0) {
      this.signallingAccessToken = accessToken;
    }

    // Avoid racing two connects to the same target from different React effects.
    if (this.activeConnectPromise && this.activeConnectTarget === normalizedUrl) {
      transportLog('info', '[dbTransport] connect deduplicated onto an in-flight attempt', {
        target: normalizedUrl,
      });
      return this.activeConnectPromise;
    }

    if (this.isConnected() || this.channel || this.pc) {
      this.disconnectCurrentConnection();
    }

    this.lastServerUrl = normalizedUrl;
    if (providedDiscoveryUuid) {
      this.lastDiscoveryUuid = providedDiscoveryUuid;
    }
    this.shouldAutoReconnect = true;
    this.clearReconnectTimer();
    if (this.reconnectAttempt === 0) {
      this.setReconnecting(false);
    }

    // Logged rather than thrown silently: on the reconnect path these two throws are swallowed
    // by the retry loop, which then spins forever on a precondition that will never change on
    // its own — indistinguishable, from the outside, from a reconnect that is never attempted.
    if (!this.signallingAccessToken) {
      transportLog('error', '[dbTransport] cannot connect: no access token for signalling', {
        target: normalizedUrl,
      });
      throw new Error('Missing access token for signalling');
    }
    if (!effectiveDiscoveryUuid) {
      transportLog('error', '[dbTransport] cannot connect: no discovery UUID for signalling', {
        target: normalizedUrl,
      });
      throw new Error('Missing discovery UUID for signalling');
    }

    const connectPromise = new Promise<void>((resolve, reject) => {
      let connectTimeoutHandle: ReturnType<typeof setTimeout> | undefined;
      const clearConnectTimeout = (): void => {
        if (connectTimeoutHandle !== undefined) {
          clearTimeout(connectTimeoutHandle);
          connectTimeoutHandle = undefined;
        }
      };
      // Settles the in-flight connect with a failure. Registered on the instance so an
      // external `disconnect()` (e.g. the user cancelling the approval modal) can abort
      // the attempt immediately, instead of leaving it pending until a connect timeout
      // fires. The identity guard ignores stale closures from a superseded attempt.
      const rejectConnect = (error: Error): void => {
        if (this.activeConnectReject !== rejectConnect) return;
        this.activeConnectReject = null;
        clearConnectTimeout();
        reject(error);
      };
      this.activeConnectReject = rejectConnect;
      const armConnectTimeout = (phase: string, ms: number): void => {
        clearConnectTimeout();
        connectTimeoutHandle = setTimeout(() => {
          transportLog('warn', '[dbTransport] connect timeout fired', {
            phase,
            timeoutMs: ms,
            target: normalizedUrl,
            pcConnectionState: this.pc?.connectionState ?? 'none',
            channelReadyState: this.channel?.readyState ?? 'none',
            iceConnectionState: this.pc?.iceConnectionState ?? 'none',
          });
          // While awaiting the host's auth response the channel is already open and
          // the host user is being prompted to accept; a timeout here means they
          // never answered, which the UI surfaces differently from a network failure.
          rejectConnect(
            new Error(
              phase === 'awaiting-host-auth' ? 'Approval timeout' : 'WebRTC connection timeout'
            )
          );
          this.disconnectCurrentConnection();
        }, ms);
      };

      armConnectTimeout('until-remote-answer', CONNECT_SIGNALING_PHASE_TIMEOUT_MS);

      void (async () => {
        let pc: RTCPeerConnection;
        let channel: RTCDataChannel;

        try {
          const signallingDeadlineTs = Date.now() + CONNECT_SIGNALING_PHASE_TIMEOUT_MS;
          const { sessionId: sessionPk, rtcConfiguration } = await this.createSignallingSession(
            normalizedUrl,
            effectiveDiscoveryUuid
          );
          const sessionPath = `api/v1/discovery/webrtc/${encodeURIComponent(sessionPk)}`;
          transportLog('info', '[dbTransport] signalling session created', {
            target: normalizedUrl,
            sessionId: sessionPk,
            discoveryUuid: effectiveDiscoveryUuid,
            iceServerCount: rtcConfiguration.iceServers?.length ?? 0,
          });

          pc = new RTCPeerConnection(rtcConfiguration);
          channel = pc.createDataChannel('db', { ordered: true });
          // Spec default is "blob"; Chromium alone defaults to "arraybuffer". Pinning it
          // puts every browser on the synchronous decode path in `onmessage` below, which
          // is the only one that cannot reorder frames.
          channel.binaryType = 'arraybuffer';

          this.pc = pc;
          this.channel = channel;
          this.setWaitingForApproval(true);
          const isCurrentAttempt = (): boolean => this.pc === pc && this.channel === channel;

          /** Serialises Blob frame decoding; see the Blob branch in `onmessage`. */
          let blobDecodeQueue: Promise<void> = Promise.resolve();
          let disconnectedGraceTimer: ReturnType<typeof setTimeout> | null = null;
          const clearDisconnectedGrace = (): void => {
            if (disconnectedGraceTimer === null) return;
            clearTimeout(disconnectedGraceTimer);
            disconnectedGraceTimer = null;
          };

          pc.oniceconnectionstatechange = () => {
            transportLog('info', '[dbTransport] iceConnectionState changed', {
              target: normalizedUrl,
              sessionId: sessionPk,
              iceConnectionState: pc.iceConnectionState,
              connectionState: pc.connectionState,
            });
          };

          pc.onconnectionstatechange = () => {
            if (!isCurrentAttempt()) {
              return;
            }
            transportLog('info', '[dbTransport] connectionState changed', {
              target: normalizedUrl,
              sessionId: sessionPk,
              connectionState: pc.connectionState,
              iceConnectionState: pc.iceConnectionState,
            });
            if (pc.connectionState === 'failed' || pc.connectionState === 'closed') {
              clearDisconnectedGrace();
              this.handleConnectionLost();
              return;
            }

            if (pc.connectionState === 'disconnected') {
              // Recoverable — give it a window to come back before tearing anything down.
              if (disconnectedGraceTimer !== null) {
                return;
              }
              disconnectedGraceTimer = setTimeout(() => {
                disconnectedGraceTimer = null;
                // A teardown that happened meanwhile (the data channel closing, say)
                // already detached this attempt; nothing left to do.
                if (!isCurrentAttempt() || pc.connectionState === 'connected') {
                  return;
                }
                transportLog(
                  'warn',
                  '[dbTransport] connection stayed disconnected; treating as lost',
                  {
                    target: normalizedUrl,
                    sessionId: sessionPk,
                    connectionState: pc.connectionState,
                    iceConnectionState: pc.iceConnectionState,
                  }
                );
                this.handleConnectionLost();
              }, CONNECTION_DISCONNECTED_GRACE_MS);
              return;
            }

            if (pc.connectionState === 'connected') {
              clearDisconnectedGrace();
            }
          };

          channel.onclose = () => {
            if (!isCurrentAttempt()) {
              return;
            }
            transportLog('info', '[dbTransport] data channel closed', {
              target: normalizedUrl,
              sessionId: sessionPk,
              pcConnectionState: pc.connectionState,
              channelReadyState: channel.readyState,
            });
            this.handleConnectionLost();
          };

          channel.onerror = () => {
            if (!isCurrentAttempt()) {
              return;
            }
            transportLog('warn', '[dbTransport] data channel error', {
              target: normalizedUrl,
              pcConnectionState: pc.connectionState,
              channelReadyState: channel.readyState,
            });
            this.setWaitingForApproval(false);

            // An error on an attempt still in flight fails that attempt, and whoever
            // asked for it (a caller, or the reconnect loop) decides what happens next.
            if (this.activeConnectReject !== null) {
              clearConnectTimeout();
              rejectConnect(new Error('WebRTC data channel failed'));
              return;
            }

            // On an established connection this *is* the link dying. WebKit reports it
            // here and closes the channel after; Chromium goes straight to `onclose` and
            // never fires this at all. Handling it directly means the retry loop does not
            // depend on a close event that may not follow. The teardown is idempotent,
            // so the `onclose` that WebKit does send afterwards is a no-op.
            this.handleConnectionLost();
          };

          channel.onopen = () => {
            if (!isCurrentAttempt()) {
              return;
            }
            transportLog('info', '[dbTransport] data channel open (offerer)', {
              target: normalizedUrl,
              sessionId: sessionPk,
              pcConnectionState: pc.connectionState,
              iceConnectionState: pc.iceConnectionState,
              channelReadyState: channel.readyState,
            });
            armConnectTimeout('awaiting-host-auth', CONNECT_AUTH_RESPONSE_TIMEOUT_MS);
          };

          channel.onmessage = (event: MessageEvent) => {
            if (!isCurrentAttempt()) {
              return;
            }
            if (typeof event.data === 'string') {
              let parsed: unknown;
              try {
                parsed = JSON.parse(event.data);
              } catch {
                return;
              }

              if (ChunkReassembler.isChunkEnvelope(parsed)) {
                const { completePayload, error } = this.chunkReassembler.addChunk(
                  parsed,
                  'transport'
                );
                if (error) {
                  transportLog('warn', '[dbTransport] dropping malformed chunked message', {
                    chunkId: parsed.chunkId,
                    error,
                  });
                  return;
                }
                if (!completePayload) {
                  return;
                }
                this.handleStringMessage(completePayload);
                return;
              }

              if (
                typeof parsed === 'object' &&
                parsed !== null &&
                (parsed as Record<string, unknown>).type === 'auth'
              ) {
                const authResponse = parsed as DbAuthResponse;
                transportLog('info', '[dbTransport] received auth response', {
                  target: normalizedUrl,
                  authenticated: authResponse.authenticated,
                  clientId: authResponse.clientId,
                  pcConnectionState: pc.connectionState,
                  channelReadyState: channel.readyState,
                });
                clearConnectTimeout();
                this.setWaitingForApproval(false);

                if (authResponse.authenticated) {
                  this.activeConnectReject = null;
                  this.reconnectAttempt = 0;
                  this.clearReconnectTimer();
                  this.setReconnecting(false);
                  this.setConnected(true);
                  resolve();
                } else {
                  this.shouldAutoReconnect = false;
                  this.clearReconnectTimer();
                  this.setReconnecting(false);
                  rejectConnect(new Error('Authentication denied'));
                  this.disconnectCurrentConnection();
                }
                return;
              }

              this.handleStringMessage(event.data);
              return;
            }

            if (event.data instanceof ArrayBuffer) {
              const data = new Uint8Array(event.data);
              const jsonText = this.tryParseJsonTextFromBinary(data);
              if (jsonText !== null) {
                this.handleStringMessage(jsonText);
                return;
              }
              this.handleIncomingBinaryChunk(data);
              return;
            }

            // Fallback for a peer that ignores `binaryType` (or a runtime that has no
            // arraybuffer support). Decoding a Blob is async and separate
            // `arrayBuffer()` calls carry no ordering guarantee, so they are chained
            // through a queue instead of each racing on its own — out-of-order chunks
            // would rebuild an image that is scrambled yet still the promised size,
            // which the completion check cannot catch.
            if (event.data instanceof Blob) {
              const blob = event.data;
              blobDecodeQueue = blobDecodeQueue
                .then(async () => {
                  const data = new Uint8Array(await blob.arrayBuffer());
                  const jsonText = this.tryParseJsonTextFromBinary(data);
                  if (jsonText !== null) {
                    this.handleStringMessage(jsonText);
                    return;
                  }
                  this.handleIncomingBinaryChunk(data);
                })
                .catch((error: unknown) => {
                  // Swallowed so one bad frame cannot wedge the queue; the transfer
                  // it belonged to fails on its own size check or timeout.
                  transportLog('warn', '[dbTransport] failed to decode binary frame', { error });
                });
            }
          };

          transportLog('info', '[dbTransport] creating local offer', {
            target: normalizedUrl,
            sessionId: sessionPk,
          });
          const offer = await pc.createOffer();
          await pc.setLocalDescription(offer);
          const iceGatheringCompleted = await this.waitForIceGatheringComplete(
            pc,
            ICE_GATHERING_TIMEOUT_MS
          );
          if (!iceGatheringCompleted) {
            transportLog(
              'warn',
              '[dbTransport] local ICE gathering timed out; continuing with partial offer SDP',
              {
                target: normalizedUrl,
                sessionId: sessionPk,
                iceGatheringState: pc.iceGatheringState,
              }
            );
          }
          transportLog('info', '[dbTransport] local description ready for non-trickle offer', {
            target: normalizedUrl,
            sessionId: sessionPk,
            iceGatheringState: pc.iceGatheringState,
          });

          const sdpOffer = stripEndOfCandidates(pc.localDescription?.sdp ?? '');
          if (!sdpOffer) {
            throw new Error('Missing SDP offer');
          }

          const headers = this.signallingAccessToken
            ? { Authorization: 'Bearer ' + this.signallingAccessToken }
            : undefined;
          const response = await axios.post(
            `${SIGNALLING_API_BASE}/${sessionPath}/offer/`,
            { sdpOffer },
            { headers }
          );
          const json = response.data as Record<string, unknown>;
          let sdpAnswer = this.extractAnswerSdp(json);
          transportLog('info', '[dbTransport] offer response received', {
            target: normalizedUrl,
            hasInlineAnswer: Boolean(sdpAnswer),
          });
          if (!sdpAnswer) {
            sdpAnswer = await this.pollSessionForAnswerSdp(sessionPath, signallingDeadlineTs);
            transportLog('info', '[dbTransport] answer received via polling', {
              target: normalizedUrl,
              sessionId: sessionPk,
            });
          }

          await pc.setRemoteDescription({ type: 'answer', sdp: sdpAnswer });
          transportLog('info', '[dbTransport] applied remote answer SDP', {
            target: normalizedUrl,
            sessionId: sessionPk,
            source: 'https',
            iceConnectionState: pc.iceConnectionState,
            connectionState: pc.connectionState,
          });
          armConnectTimeout('post-answer-data-channel-and-auth', CONNECT_POST_ANSWER_TIMEOUT_MS);
        } catch (error) {
          // Everything from session creation to the remote answer lands here. Without a log
          // a failed attempt leaves no trace at all: the last line is whatever preceded the
          // connect, which reads exactly like the reconnect never having been tried.
          transportLog('error', '[dbTransport] connect attempt failed', {
            target: normalizedUrl,
            discoveryUuid: effectiveDiscoveryUuid,
            pcConnectionState: this.pc?.connectionState ?? 'none',
            channelReadyState: this.channel?.readyState ?? 'none',
            error,
          });
          rejectConnect(error instanceof Error ? error : new Error('WebRTC connection failed'));
          this.disconnectCurrentConnection();
        }
      })();
    });

    // The guard compares against `trackedPromise` — the wrapper — because that is what the
    // field holds. Comparing against `connectPromise` never matches, which would leave a
    // settled attempt pinned here forever and turn every later connect to the same target
    // into a no-op that returns it (reconnects included).
    const trackedPromise: Promise<void> = connectPromise.finally(() => {
      if (this.activeConnectPromise === trackedPromise) {
        this.activeConnectPromise = null;
        this.activeConnectTarget = null;
      }
    });
    this.activeConnectTarget = normalizedUrl;
    this.activeConnectPromise = trackedPromise;

    return trackedPromise;
  }

  /**
   * Opens a short-lived WebRTC connection with a "probe" data channel to verify that a
   * server is reachable without triggering an authentication request. The probe follows
   * the same HTTPS-only signalling path as normal connections.
   *
   * Reachability is decided by the *peer connection* reaching `connected`, not by the data channel
   * opening. The host tears a probe channel — and the whole peer connection carrying it — down the
   * instant its own side opens (`cloudSignallingHost`, which closes the channel and then the peer
   * connection through the connection manager). Settling on `onopen` therefore puts the DCEP ack in
   * a race with that teardown over the same association: lose it and no `open` event is ever
   * dispatched, leaving the probe nothing to settle on but its timeout. Whether a queued `open`
   * survives an SCTP reset arriving alongside it is implementation-specific, which is why this
   * surfaced as an occasional Firefox-only failure on every OS.
   *
   * DTLS completing already proves the host is reachable, and it necessarily precedes the host
   * seeing the channel at all — so this signal cannot lose that race. The channel is still created,
   * because a peer connection with no media and no data channel has nothing to negotiate.
   */
  async probe(
    serverUrl: string,
    _accessToken: string,
    discoveryUuid: string,
    signal?: AbortSignal
  ): Promise<boolean> {
    const normalizedUrl = serverUrl.trim().replace(/\/+$/, '');
    const normalizedDiscoveryUuid = typeof discoveryUuid === 'string' ? discoveryUuid.trim() : '';
    if (!normalizedDiscoveryUuid) {
      transportLog('warn', '[dbTransport] probe skipped: missing discovery UUID', {
        target: normalizedUrl,
      });
      return false;
    }
    void _accessToken;

    return new Promise<boolean>(resolve => {
      let settled = false;
      let pc: RTCPeerConnection | null = null;
      let channel: RTCDataChannel | null = null;
      let timer: ReturnType<typeof setTimeout> | undefined;

      // Aborted when a sibling probe wins the race, so this peer connection is torn down
      // immediately instead of dangling until its own timeout fires.
      const onAbort = (): void => done(false, 'aborted by sibling probe');

      // Every terminal path names itself. A probe that returns `false` used to leave no trace
      // of *why* — timeout, abort, ICE failure and a signalling error were indistinguishable
      // from each other and from a host that is simply switched off.
      const done = (result: boolean, reason: string, detail?: unknown): void => {
        if (settled) return;
        settled = true;
        if (timer !== undefined) {
          clearTimeout(timer);
        }
        signal?.removeEventListener('abort', onAbort);
        transportLog(result ? 'info' : 'warn', '[dbTransport] probe settled', {
          target: normalizedUrl,
          discoveryUuid: normalizedDiscoveryUuid,
          reachable: result,
          reason,
          pcConnectionState: pc?.connectionState ?? 'none',
          iceConnectionState: pc?.iceConnectionState ?? 'none',
          channelReadyState: channel?.readyState ?? 'none',
          ...(detail === undefined ? {} : { detail }),
        });
        try {
          channel?.close();
          pc?.close();
        } catch {
          // Ignore close errors during probe cleanup.
        }
        resolve(result);
      };

      const armProbeTimeout = (phase: string, ms: number): void => {
        if (timer !== undefined) {
          clearTimeout(timer);
        }
        timer = setTimeout(() => done(false, `timeout awaiting ${phase}`), ms);
      };

      // Phased like `connect`, and for the same reason. One flat budget has to be short enough
      // to call a switched-off host unreachable quickly, which leaves a live-but-slow host no
      // room at all: signalling alone can spend seconds on ICE gathering at *both* ends before
      // either peer has anything to hand the other, and the answer poll backs off on top of that.
      armProbeTimeout('signalling', PROBE_SIGNALLING_TIMEOUT_MS);

      if (signal?.aborted) {
        done(false, 'aborted before start');
        return;
      }
      signal?.addEventListener('abort', onAbort);

      void (async () => {
        try {
          // Bounded by this probe's own signalling budget rather than a connect's, so giving
          // up here also stops the poll loop instead of leaving it hitting the backend for
          // another 30s on a result nobody is waiting for any more.
          const signallingDeadlineTs = Date.now() + PROBE_SIGNALLING_TIMEOUT_MS;
          const { sessionId: sessionPk, rtcConfiguration } = await this.createSignallingSession(
            normalizedUrl,
            normalizedDiscoveryUuid
          );
          const sessionPath = `api/v1/discovery/webrtc/${encodeURIComponent(sessionPk)}`;

          pc = new RTCPeerConnection(rtcConfiguration);
          channel = pc.createDataChannel('probe');

          // Kept as a secondary success signal for a host that leaves the channel open;
          // `connected` below is what normally settles this.
          channel.onopen = () => done(true, 'probe data channel open');
          channel.onerror = () => done(false, 'probe data channel error');

          pc.onconnectionstatechange = () => {
            const state = pc?.connectionState;
            if (state === 'connected') {
              done(true, 'peer connection connected');
              return;
            }
            // `disconnected` is recoverable (see CONNECTION_DISCONNECTED_GRACE_MS) and it is
            // also what the host's own teardown looks like from here, so it must not count
            // as unreachable. A probe is short-lived enough that the phase timeout is the
            // only deadline it needs; only genuinely terminal states settle it early.
            if (state === 'failed' || state === 'closed') {
              done(false, `peer connection ${state}`);
            }
          };

          const offer = await pc.createOffer();
          await pc.setLocalDescription(offer);
          const iceGatheringCompleted = await this.waitForIceGatheringComplete(
            pc,
            PROBE_ICE_GATHERING_TIMEOUT_MS
          );
          if (!iceGatheringCompleted) {
            transportLog(
              'warn',
              '[dbTransport] probe ICE gathering timed out; continuing with partial offer SDP',
              {
                target: normalizedUrl,
                sessionId: sessionPk,
                iceGatheringState: pc.iceGatheringState,
              }
            );
          }

          const sdpOffer = stripEndOfCandidates(pc.localDescription?.sdp ?? '');
          if (!sdpOffer) throw new Error('Missing SDP offer');

          const headers = this.signallingAccessToken
            ? { Authorization: 'Bearer ' + this.signallingAccessToken }
            : undefined;
          const response = await axios.post(
            `${SIGNALLING_API_BASE}/${sessionPath}/offer/`,
            { sdpOffer },
            { headers }
          );
          const json = response.data as Record<string, unknown>;
          let sdpAnswer = this.extractAnswerSdp(json);
          if (!sdpAnswer) {
            sdpAnswer = await this.pollSessionForAnswerSdp(sessionPath, signallingDeadlineTs);
          }

          await pc.setRemoteDescription({ type: 'answer', sdp: sdpAnswer });
          armProbeTimeout('connectivity checks and DTLS', PROBE_POST_ANSWER_TIMEOUT_MS);
        } catch (error) {
          done(false, 'signalling failed', error);
        }
      })();
    });
  }

  disconnect(): void {
    this.shouldAutoReconnect = false;
    this.reconnectAttempt = 0;
    this.lastServerUrl = null;
    this.lastDiscoveryUuid = null;
    this.signallingAccessToken = null;
    this.clearReconnectTimer();
    this.setReconnecting(false);
    this.disconnectCurrentConnection();
  }

  async send<T>(type: DbMessageType, payload: unknown = {}): Promise<T> {
    if (!this.isConnected() || !this.channel) {
      throw new Error('DataChannel not connected');
    }

    const id = uuidv4();
    const request: DbRequest = { id, type, payload: this.convertArrayBuffersToBase64(payload) };

    return new Promise<T>((resolve, reject) => {
      const timer = setTimeout(() => {
        this.pendingRequests.delete(id);
        reject(new Error(`Request timeout: ${type}`));
      }, this.getRequestTimeoutMs(type));

      this.pendingRequests.set(id, {
        resolve: resolve as (value: unknown) => void,
        reject,
        timer,
      });

      void this.sendRawThroughDataChannel(JSON.stringify(request)).catch((error: unknown) => {
        const pending = this.pendingRequests.get(id);
        if (!pending) {
          return;
        }
        this.pendingRequests.delete(id);
        clearTimeout(pending.timer);
        pending.reject(error instanceof Error ? error : new Error('Failed to send WebRTC payload'));
      });
    });
  }

  private async sendControlMessage(message: StreamControlMessage): Promise<void> {
    await this.sendRawThroughDataChannel(JSON.stringify(message));
  }

  private async uploadFile(
    transferId: string,
    file: File,
    purpose: StreamOpenControl['purpose'],
    relatedRequestId?: string
  ): Promise<void> {
    if (!this.channel || !this.isConnected()) {
      throw new Error('DataChannel not connected');
    }
    const uploadPromise = new Promise<void>((resolve, reject) => {
      const timer = this.createTransferTimeout(() => {
        this.pendingUploadTransfers.delete(transferId);
        reject(new Error(`Stream transfer timeout: ${transferId}`));
      });
      this.pendingUploadTransfers.set(transferId, {
        resolve,
        reject,
        totalBytes: file.size,
        ackedBytes: 0,
        timer,
      });
    });

    await this.sendControlMessage({
      type: 'streamOpen',
      transferId,
      direction: 'upload',
      purpose,
      sizeBytes: file.size,
      mimeType: file.type || 'application/octet-stream',
      filename: file.name,
      relatedRequestId,
    });

    const chunkSize = DATA_CHANNEL_BINARY_CHUNK_BYTES;
    for (let offset = 0; offset < file.size; offset += chunkSize) {
      const slice = file.slice(offset, Math.min(file.size, offset + chunkSize));
      const data = new Uint8Array(await slice.arrayBuffer());
      await this.waitForBufferedAmountDrain();
      if (!this.channel || this.channel.readyState !== 'open') {
        throw new Error('DataChannel closed during upload');
      }
      try {
        this.channel.send(data);
      } catch {
        throw new Error('Failed to send upload chunk');
      }
      const pending = this.pendingUploadTransfers.get(transferId);
      if (!pending) {
        break;
      }
      if (pending.ackedBytes + STREAM_ACK_WINDOW_BYTES < offset) {
        await new Promise<void>(resolve => setTimeout(resolve, 5));
      }
    }

    await this.sendControlMessage({ type: 'streamComplete', transferId });
    await uploadPromise;
  }

  private async waitForIncomingTransfer(transferId: string): Promise<Blob> {
    let promise = this.pendingIncomingTransferPromises.get(transferId);
    if (!promise) {
      const start = Date.now();
      while (!promise && Date.now() - start < 10_000) {
        await new Promise(resolve => setTimeout(resolve, 20));
        promise = this.pendingIncomingTransferPromises.get(transferId);
      }
    }
    if (!promise) {
      throw new Error(`No incoming stream for transfer ${transferId}`);
    }
    try {
      return await promise;
    } finally {
      this.pendingIncomingTransferPromises.delete(transferId);
    }
  }

  async sendFileAndRequest<T>(
    type: DbMessageType,
    file: File,
    payload: Record<string, unknown>,
    purpose: StreamOpenControl['purpose']
  ): Promise<T> {
    const transferId = uuidv4();
    await this.enqueueTransfer('upload', () => this.uploadFile(transferId, file, purpose));
    const response = await this.send<T>(type, { ...payload, transferId });
    return response;
  }

  async requestBlobResponse(
    type: DbMessageType,
    payload: Record<string, unknown>,
    purpose: StreamOpenControl['purpose']
  ): Promise<Blob> {
    // Queued around the request too, not just the receive: the host starts streaming as soon as
    // it has routed the request, so overlapping requests are what produce overlapping streams.
    // Holding the queue across the whole exchange also protects us from an older host that does
    // not serialise its own sends.
    return this.enqueueTransfer('download', async () => {
      const transferId = uuidv4();
      const response = await this.send<{ transferId: string; mimeType?: string }>(type, {
        ...payload,
        __stream: true,
        streamTransferId: transferId,
        streamPurpose: purpose,
      });
      const inboundTransferId = response?.transferId ?? transferId;
      return this.waitForIncomingTransfer(inboundTransferId);
    });
  }

  private isStreamControlMessage(value: unknown): value is StreamControlMessage {
    if (!value || typeof value !== 'object') {
      return false;
    }
    const type = (value as { type?: unknown }).type;
    return (
      type === 'streamOpen' ||
      type === 'streamAck' ||
      type === 'streamComplete' ||
      type === 'streamCancel' ||
      type === 'streamError'
    );
  }

  private handleStringMessage(raw: string): void {
    let message: DbResponse | DbServerEvent;
    try {
      message = JSON.parse(raw) as DbResponse | DbServerEvent;
    } catch {
      return;
    }

    if (this.isStreamControlMessage(message)) {
      this.handleStreamControl(message);
      return;
    }

    if ('event' in message) {
      if (message.event === 'hostRestarting') {
        this.handleHostRestartSignal();
        return;
      }
      const listeners = this.serverEventListeners.get(message.event) ?? [];
      for (const listener of listeners) {
        listener(message.payload);
      }
      return;
    }

    const response = message as DbResponse;

    const pending = this.pendingRequests.get(response.id);
    if (!pending) return;

    this.pendingRequests.delete(response.id);
    clearTimeout(pending.timer);

    if (response.success) {
      pending.resolve(response.data);
    } else {
      pending.reject(new Error(response.error ?? 'Unknown error'));
    }
  }

  private handleStreamControl(control: StreamControlMessage): void {
    switch (control.type) {
      case 'streamOpen':
        this.handleIncomingStreamOpen(control);
        return;
      case 'streamAck':
        this.handleIncomingStreamAck(control);
        return;
      case 'streamComplete':
        this.handleIncomingStreamComplete(control);
        return;
      case 'streamError':
        this.handleIncomingStreamError(control);
        return;
      case 'streamCancel':
        this.handleIncomingStreamError({
          type: 'streamError',
          transferId: control.transferId,
          error: control.reason ?? 'Stream cancelled',
        });
        return;
    }
  }

  private handleIncomingStreamOpen(control: StreamOpenControl): void {
    if (control.direction !== 'download') {
      return;
    }
    const existing = this.incomingTransfers.get(control.transferId);
    if (existing) {
      clearTimeout(existing.timer);
      existing.reject(new Error(`Duplicate stream transfer id: ${control.transferId}`));
    }

    // A second stream opening while one is still running means the peer is not serialising
    // (an older host). Binary frames carry no transfer id, so from here on neither transfer can
    // be trusted — fail the one already in progress with a diagnosable reason instead of
    // letting it silently absorb the newcomer's bytes.
    const activeTransferId = this.activeIncomingTransferId;
    if (activeTransferId && activeTransferId !== control.transferId) {
      const active = this.incomingTransfers.get(activeTransferId);
      if (active) {
        transportLog('error', '[dbTransport] overlapping incoming streams', {
          activeTransferId,
          incomingTransferId: control.transferId,
        });
        clearTimeout(active.timer);
        this.incomingTransfers.delete(activeTransferId);
        active.reject(
          new Error(`Stream ${activeTransferId} was interrupted by an overlapping transfer`)
        );
      }
    }

    let resolveTransfer: (result: Blob) => void = () => undefined;
    let rejectTransfer: (reason: Error) => void = () => undefined;

    const transfer: IncomingTransfer = {
      resolve: result => resolveTransfer(result),
      reject: reason => rejectTransfer(reason),
      totalBytes: control.sizeBytes,
      receivedBytes: 0,
      mimeType: control.mimeType,
      chunks: [],
      timer: this.createTransferTimeout(() => undefined),
    };

    const promise = new Promise<Blob>((resolve, reject) => {
      resolveTransfer = resolve;
      rejectTransfer = reject;
    });

    transfer.timer = this.createTransferTimeout(() => {
      this.incomingTransfers.delete(control.transferId);
      if (this.activeIncomingTransferId === control.transferId) {
        this.activeIncomingTransferId = null;
      }
      transfer.reject(new Error(`Incoming stream timeout: ${control.transferId}`));
    });
    this.incomingTransfers.set(control.transferId, transfer);
    this.activeIncomingTransferId = control.transferId;
    this.pendingIncomingTransferPromises.set(control.transferId, promise);
  }

  private handleIncomingStreamAck(control: StreamAckControl): void {
    const upload = this.pendingUploadTransfers.get(control.transferId);
    if (!upload) {
      return;
    }

    upload.ackedBytes = Math.max(upload.ackedBytes, control.ackBytes);
    this.refreshUploadTransferTimeout(control.transferId);
    if (control.done || upload.ackedBytes >= upload.totalBytes) {
      clearTimeout(upload.timer);
      this.pendingUploadTransfers.delete(control.transferId);
      upload.resolve();
    }
  }

  private handleIncomingBinaryChunk(chunk: Uint8Array): void {
    const transferId = this.activeIncomingTransferId;
    if (!transferId) {
      return;
    }
    const transfer = this.incomingTransfers.get(transferId);
    if (!transfer) {
      return;
    }
    transfer.chunks.push(chunk);
    transfer.receivedBytes += chunk.byteLength;
    this.refreshIncomingTransferTimeout(transferId);
  }

  private handleIncomingStreamComplete(control: StreamCompleteControl): void {
    const transfer = this.incomingTransfers.get(control.transferId);
    if (!transfer) {
      return;
    }

    clearTimeout(transfer.timer);
    this.incomingTransfers.delete(control.transferId);
    if (this.activeIncomingTransferId === control.transferId) {
      this.activeIncomingTransferId = null;
    }

    // A transfer that did not receive the bytes it was promised must not resolve. These are
    // radiographs: handing back a short or over-long blob renders as a truncated or garbled
    // image that looks like a real one, which is a far worse failure than an error.
    if (transfer.totalBytes > 0 && transfer.receivedBytes !== transfer.totalBytes) {
      transportLog('error', '[dbTransport] incoming stream size mismatch', {
        transferId: control.transferId,
        expectedBytes: transfer.totalBytes,
        receivedBytes: transfer.receivedBytes,
      });
      transfer.reject(
        new Error(
          `Incomplete stream ${control.transferId}: expected ${transfer.totalBytes} bytes, received ${transfer.receivedBytes}`
        )
      );
      return;
    }

    const blobParts = transfer.chunks.map(chunk => new Uint8Array(chunk));
    const blob = new Blob(blobParts, { type: transfer.mimeType ?? 'application/octet-stream' });
    transfer.resolve(blob);
  }

  private handleIncomingStreamError(control: StreamErrorControl): void {
    const upload = this.pendingUploadTransfers.get(control.transferId);
    if (upload) {
      clearTimeout(upload.timer);
      this.pendingUploadTransfers.delete(control.transferId);
      upload.reject(new Error(control.error));
    }

    const transfer = this.incomingTransfers.get(control.transferId);
    if (transfer) {
      clearTimeout(transfer.timer);
      this.incomingTransfers.delete(control.transferId);
      if (this.activeIncomingTransferId === control.transferId) {
        this.activeIncomingTransferId = null;
      }
      transfer.reject(new Error(control.error));
    }
  }

  private rejectAllPending(reason: string): void {
    for (const [, pending] of this.pendingRequests) {
      clearTimeout(pending.timer);
      pending.reject(new Error(reason));
    }
    this.pendingRequests.clear();
  }

  private rejectAllPendingTransfers(reason: string): void {
    for (const [transferId, pending] of this.pendingUploadTransfers) {
      clearTimeout(pending.timer);
      pending.reject(new Error(reason));
      this.pendingUploadTransfers.delete(transferId);
    }

    for (const [transferId, incoming] of this.incomingTransfers) {
      clearTimeout(incoming.timer);
      incoming.reject(new Error(reason));
      this.incomingTransfers.delete(transferId);
    }

    this.pendingIncomingTransferPromises.clear();
    this.activeIncomingTransferId = null;
  }

  private async sendRawThroughDataChannel(raw: string): Promise<void> {
    if (!this.channel) {
      throw new Error('DataChannel not connected');
    }

    const payloadBytes = new TextEncoder().encode(raw).length;
    if (payloadBytes <= DATA_CHANNEL_MAX_CHUNK_BYTES) {
      await this.waitForBufferedAmountDrain();
      this.channel.send(raw);
      return;
    }

    const chunkId = uuidv4();
    const parts = this.splitStringByUtf8ByteLength(raw, DATA_CHANNEL_MAX_CHUNK_BYTES);
    const total = parts.length;
    for (let seq = 0; seq < total; seq += 1) {
      const envelope: ChunkEnvelope = {
        __wdxChunk: true,
        chunkId,
        seq,
        total,
        data: parts[seq],
      };
      await this.waitForBufferedAmountDrain();
      this.channel.send(JSON.stringify(envelope));
    }
  }
}

export const dbTransport = new DatabaseTransport();

export const isDatabaseTransportReady = (): boolean => dbTransport.isConnected();
