import dicomImageLoader from '@cornerstonejs/dicom-image-loader';

import FileLoader from './fileLoader';
import PDFFileLoader from './pdfFileLoader';
import DICOMFileLoader from './dicomFileLoader';
import ImageFileLoader from './imageFileLoader';

class FileLoaderService extends FileLoader {
  fileType;
  loader;
  constructor(file) {
    super();
    const fileType = file && file.type;
    this.loader = this.getLoader(fileType);
    this.fileType = this.loader.fileType;
  }

  addFile(file) {
    const imageId = dicomImageLoader.wadouri.fileManager.add(file);
    if (this.fileType === 'image/png') {
      // Do not use dicomfile schema for png files
      return 'pngfile:' + imageId.split(':')[1];
    }
    return imageId;
  }

  loadFile(file, imageId) {
    return this.loader.loadFile(file, imageId);
  }

  getDataset(image, imageId, options = {}) {
    return this.loader.getDataset(image, imageId, options);
  }

  getLoader(fileType) {
    if (fileType === 'application/pdf') {
      return PDFFileLoader;
    } else if (fileType === 'image/png') {
      return ImageFileLoader;
    } else {
      // Default to dicom loader
      return DICOMFileLoader;
    }
  }
}

export default FileLoaderService;
