import { NumberPair } from 'extensions/cornerstone/src/types/Panoramic';
import { Point3 } from '@cornerstonejs/core/types';

const getMinMaxLayer = (scalarData: ArrayLike<number>, dimensions: Point3): NumberPair => {
  const [layerWidth, layerHeight, _] = dimensions;

  // Ignore rows with empty data
  const offsetMin = (scalarData as any).findIndex((value: number) => value > -1000);
  const offsetMax = (scalarData as any).findLastIndex((value: number) => value > -1000);
  const minLayer = Math.floor(offsetMin / layerWidth / layerHeight);
  const maxLayer = Math.floor(offsetMax / layerWidth / layerHeight) + 1;

  return [minLayer, maxLayer];
};

const getParameters = (volumeSpacing: number) => {
  return {
    dentascanWidth: Math.round(28 / volumeSpacing),
    dentalCurveAipWidth: Math.round(16 / volumeSpacing),
    dentalCurveWidth: Math.round(16 / volumeSpacing),
  };
};

export { getMinMaxLayer, getParameters };
