import { Bounds, NumberPair, Points } from 'extensions/cornerstone/src/types/Panoramic';
import { polynomialLSF } from './computeDentalCurveUtils';
import { Point3 } from '@cornerstonejs/core/types';
import { getNormalVector, getTangentVector } from './mathUtils';
import { binaryDilateDisk, spatialClustering } from './imageProcessingUtils';
import { getParameters } from './cbctUtils';
const skmeans = require('skmeans');

// Returns the scalar data projected on the sagittal axis, using the max of values along X axis
const getSagittalDataMax = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair
) => {
  const [layerWidth, layerHeight, _] = dimensions;
  const layerSize = layerWidth * layerHeight;
  const nbLayers = maxLayer - minLayer;

  const sagittalData = new Float32Array(layerHeight * nbLayers);
  // Iterate over Y and Z axes
  for (let k = 0; k < nbLayers; k++) {
    for (let j = 0; j < layerHeight; j++) {
      // Store max value along axis in sagittalData
      let maxVal = -Infinity;
      for (let i = 0; i < layerWidth; i++) {
        const value = scalarData[(k + minLayer) * layerSize + j * layerWidth + i];
        if (value > maxVal) {
          maxVal = value;
        }
      }
      sagittalData[k * layerHeight + j] = maxVal;
    }
  }

  return sagittalData;
};

// Returns the scalar data projected on the coronal axis, using the max of values along X axis
const getCoronalDataMax = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair
) => {
  const [layerWidth, layerHeight, _] = dimensions;
  const layerSize = layerWidth * layerHeight;
  const nbLayers = maxLayer - minLayer;

  const coronalData = new Float32Array(layerWidth * nbLayers);
  // Iterate over Y and Z axes
  for (let k = 0; k < nbLayers; k++) {
    for (let j = 0; j < layerWidth; j++) {
      // Store max value along axis in coronalData
      let maxVal = -Infinity;
      for (let i = 0; i < layerHeight; i++) {
        const value = scalarData[(k + minLayer) * layerSize + j * layerHeight + i];
        if (value > maxVal) {
          maxVal = value;
        }
      }
      coronalData[k * layerHeight + j] = maxVal;
    }
  }

  return coronalData;
};

// Returns the scalar data projected on the axial axis,
// using the mean values along Z axis between minLayer and maxLayer
const getAxialDataMean = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair
) => {
  const [layerWidth, layerHeight, _] = dimensions;
  const layerSize = layerWidth * layerHeight;
  const nbLayers = maxLayer - minLayer;

  const axialData = new Float32Array(layerWidth * layerHeight);
  // Iterate over X and Y axes
  for (let i = 0; i < layerWidth; i++) {
    for (let j = 0; j < layerHeight; j++) {
      // Store average value along axis in axialData
      let sumVal = 0;
      for (let k = minLayer; k < maxLayer; k++) {
        sumVal += scalarData[k * layerSize + j * layerWidth + i];
      }
      axialData[j * layerWidth + i] = sumVal / nbLayers;
    }
  }

  return axialData;
};

// Compute control points : points that determine piecewise linear curve function through f
// They are also the points drawn in Viewport so that user can modify if the curve is not correct
// Curve control points are only used to display a pretty curve
const computeControlPoints = (
  f: (x: number) => number,
  bounds: Bounds,
  spacing: number,
  numberBasePoints: number,
  antiAliasing: boolean
) => {
  const { dentascanWidth } = getParameters(spacing);
  const curvePoints: NumberPair[] = [];
  const innerPoints: NumberPair[] = [];
  const outerPoints: NumberPair[] = [];
  const normals: NumberPair[] = [];

  const scale = antiAliasing ? 2 : 1;

  const { minX, maxX, minY, maxY } = bounds;
  let x = maxX;
  do {
    let y = f(x);
    y = Math.min(Math.max(y, minY), maxY);
    curvePoints.push([x, y]);

    // Determine inner curve and outer curve
    const [vxNormal, vyNormal] = getNormalVector(f, x);
    const offsetX = (vxNormal * dentascanWidth) / 2;
    const offsetY = (vyNormal * dentascanWidth) / 2;
    let minPoint: NumberPair = [x - offsetX, y - offsetY];
    let maxPoint: NumberPair = [x + offsetX, y + offsetY];
    // Swap minPoint and maxPoint if minPoint is inner
    if (vyNormal < 0) {
      [minPoint, maxPoint] = [maxPoint, minPoint];
    }
    outerPoints.push(minPoint);
    innerPoints.push(maxPoint);
    normals.push([vxNormal, vyNormal]);
    x -= getTangentVector(f, x)[0] / scale;
  } while (x > minX);

  const controlPoints: NumberPair[] = [];
  const step = (curvePoints.length - 1) / (numberBasePoints - 1);
  for (let i = 0; i < numberBasePoints; i++) {
    controlPoints.push(curvePoints[Math.floor(i * step + 0.5)]);
  }

  const points: Points = { controlPoints, curvePoints, outerPoints, innerPoints, normals };

  return points;
};

// Computation of panoramic control points, which are points in the dental curve
// from where panoramic will be computed
const createControlPoints = (
  scalarData: ArrayLike<number>,
  dimensions: Point3,
  [minLayer, maxLayer]: NumberPair,
  spacing: number,
  antiAliasing: boolean = false,
  numberBasePoints: number = 11
): [Points, NumberPair] => {
  const [layerWidth, layerHeight, _] = dimensions;

  const coronalData = getCoronalDataMax(scalarData, dimensions, [minLayer, maxLayer]);

  // We select the highest value cluster on coronal view with a K-means++
  const skMeansCoronal: { it: number; k: number; idxs: number[]; centroids: number[] } = skmeans(
    coronalData,
    6
  );
  const { centroids: centroidsCoronal, idxs: idxsCoronal } = skMeansCoronal;
  const idxsMaxCoronal = centroidsCoronal.indexOf(Math.max(...centroidsCoronal));
  // Find minimal and maximal layer where one pixel is not -1000
  const firstIndex = idxsCoronal.indexOf(idxsMaxCoronal);
  const lastIndex = (idxsCoronal as any).findLastIndex(value => value === idxsMaxCoronal);
  const minTissueLayer = minLayer + Math.floor(firstIndex / layerWidth);
  const maxTissueLayer = minLayer + Math.floor(lastIndex / layerWidth) + 1;
  // TODO assert minLayer !== maxLayer
  const axialData = getAxialDataMean(scalarData, dimensions, [minTissueLayer, maxTissueLayer]);

  // K-means++ in AIP axial image data to isolate bone / jaw zone
  const skMeansResult: { it: number; k: number; idxs: number[]; centroids: number[] } = skmeans(
    axialData,
    5
  );
  const { centroids, idxs } = skMeansResult;
  const maxClusterIdx = centroids.indexOf(Math.max(...centroids));

  // Binarize array between max cluster (highest values meaning bone pixels) and other
  const binarizedArray = new Array<boolean>(axialData.length);
  for (let i = 0; i < axialData.length; i++) {
    binarizedArray[i] = idxs[i] === maxClusterIdx;
  }

  const binarizedArrayDilated: boolean[] = binaryDilateDisk(
    binarizedArray,
    layerWidth,
    layerHeight,
    5
  );

  // Find equation of polynomial going through dental zone with the use of the biggest spatial cluster
  // corresponding to our dental zone
  /* const binarizedIdx = binarizedArray.map((value, idx) => value != -1000? idx: -1000);
    const filteredIdx = binarizedIdx.filter((value) => value != -1000);
    const binarizedXy = Array.from(filteredIdx).map(i => ({ x: i % layerWidth, y: Math.floor(i / layerWidth) }));*/

  const spatialClusters = spatialClustering(binarizedArrayDilated, layerWidth, layerHeight);
  spatialClusters.sort((sc1, sc2) => sc2.length - sc1.length);
  // Indexes of biggest spatial cluster as X and Y values
  const biggestSpatialClusterXy = spatialClusters[0]?.map(i => ({
    x: i % layerWidth,
    y: Math.floor(i / layerWidth),
  }));

  // LSF method to get best fitting parabola along pixels in square
  const f = polynomialLSF(biggestSpatialClusterXy, 2).predict;

  // Find minimum and maximum of our binarized to determine where panoramic should start and where should end
  // We want control points to start at right and left jaw, so we don't use biggestCluster in this case
  // since it corresponds to the dental zone, not jaws
  let minX = Infinity;
  let maxX = -Infinity;
  for (let i = 0; i < binarizedArrayDilated.length; i++) {
    if (!binarizedArrayDilated[i]) {
      continue;
    }
    const x = i % layerWidth;
    minX = x < minX ? x : minX;
    maxX = x > maxX ? x : maxX;
  }
  const bounds: Bounds = { minX, maxX, minY: 0, maxY: layerHeight - 1 };
  const points: Points = computeControlPoints(f, bounds, spacing, numberBasePoints, antiAliasing);

  return [points, [minTissueLayer, maxTissueLayer]];
};

const regenerateControlPoints = (
  controlPoints: { x: number; y: number }[],
  dimensions: Point3,
  spacing: number,
  antiAliasing: boolean = false,
  numberBasePoints: number = 11
) => {
  const [layerWidth, layerHeight, _] = dimensions;

  // LSF method to get best fitting parabola along basePoints
  const f = polynomialLSF(controlPoints, 6).predict;

  // We need to regenerate base points, which are equitably distributed along the curve
  // The curve is bounded within the volume width
  const minX = Math.max(controlPoints[0].x, 0);
  const maxX = Math.min(controlPoints[numberBasePoints - 1].x, layerWidth - 1);
  const bounds: Bounds = { minX, maxX, minY: 0, maxY: layerHeight - 1 };
  const points: Points = computeControlPoints(f, bounds, spacing, numberBasePoints, antiAliasing);

  return points;
};

export { createControlPoints, regenerateControlPoints };
