import { Types } from '@cornerstonejs/core';
import { VoxelManager } from '@cornerstonejs/core/utilities';
import { loadFileRequest } from '@cornerstonejs/dicom-image-loader/wadouri';

function arrayBufferToImage(arrayBuffer) {
  return new Promise((resolve, reject) => {
    const arrayBufferView = new Uint8Array(arrayBuffer);
    let image, urlCreator, imageUrl;

    // Try Image decoding
    try {
      image = new Image();
      urlCreator = window.URL || window.webkitURL;
      const blob = new Blob([arrayBufferView]);
      imageUrl = urlCreator.createObjectURL(blob);
      image.src = imageUrl;
    } catch (e) {}

    image.onload = () => {
      resolve(image);
      // urlCreator.revokeObjectURL(imageUrl);
    };

    image.onerror = error => {
      // urlCreator.revokeObjectURL(imageUrl);
      reject(error);
    };
  });
}

const canvas = document.createElement('canvas');

/**
 * creates a cornerstone Image object for the specified Image and imageId
 *
 * @param image - An Image
 * @param imageId - the imageId for this image
 * @returns Cornerstone Image Object
 */
function createImage(image, imageId) {
  // extract the attributes we need
  const rows = image.naturalHeight;
  const columns = image.naturalWidth;

  function getPixelData() {
    const imageData = getImageData();

    const targetArray = new Uint8Array(imageData.width * imageData.height);
    convertImageDataToGrayScale(imageData, targetArray);

    return targetArray;
  }

  function convertImageDataToGrayScale(imageData, targetArray) {
    for (let i = 0; i < imageData.data.length / 4; i++) {
      targetArray[i] = imageData.data[i * 4];
    }
  }

  function getImageData() {
    let context;

    canvas.height = image.naturalHeight;
    canvas.width = image.naturalWidth;
    context = canvas.getContext('2d');
    context.drawImage(image, 0, 0);

    return context.getImageData(0, 0, image.naturalWidth, image.naturalHeight);
  }

  function getCanvas() {
    canvas.height = image.naturalHeight;
    canvas.width = image.naturalWidth;
    const context = canvas.getContext('2d');

    context.drawImage(image, 0, 0);

    return canvas;
  }

  const voxelManager = VoxelManager.createImageVoxelManager({
    scalarData: getPixelData(),
    width: columns,
    height: rows,
    numberOfComponents: 1,
  });

  // Extract the various attributes we need
  return {
    imageId,
    minPixelValue: 0,
    maxPixelValue: 255,
    slope: 1,
    intercept: 0,
    windowCenter: 128,
    windowWidth: 255,
    getPixelData,
    getCanvas,
    getImage: () => image,
    rows,
    columns,
    height: rows,
    width: columns,
    color: false,
    rgba: false,
    columnPixelSpacing: undefined,
    rowPixelSpacing: undefined,
    invert: false,
    sizeInBytes: rows * columns,
    numberOfComponents: 1,
    voxelManager,
    voiLUTFunction: undefined,
    dataType: Uint8Array.name as Types.PixelDataTypedArrayString,
  };
}

export default function loadPNGImage(imageId): Types.IImageLoadObject {
  const promise = new Promise<Types.IImage>(async (resolve, reject) => {
    const arrayBuffer = await loadFileRequest(imageId);
    const image = await arrayBufferToImage(arrayBuffer);
    const imageObject: Types.IImage = createImage(image, imageId);
    resolve(imageObject);
  });

  return {
    promise: promise as Promise<Types.IImage>,
    cancelFn: undefined,
  };
}
